INSERT INTO `chat_qa` (`id`, `question`, `normalized_question`, `answer`, `answer_title`, `bullets`, `category`, `keywords`, `confidence`, `source`, `usage_count`, `helpful_count`, `not_helpful_count`, `created_at`, `updated_at`) VALUES
(1, 'ما هو المعدل الطبيعي للسكر؟', 'ما هو المعدل الطبيعي للسكر', 'يختلف المعدل الطبيعي لسكر الدم حسب الحالة: للشخص السليم: صائم 70-100 mg/dL، بعد الأكل أقل من 140 mg/dL. لمريض السكري: صائم 80-130 mg/dL، بعد الأكل أقل من 180 mg/dL.', '🍬 المعدل الطبيعي للسكر', '\"[\\\"\\\\u0644\\\\u0644\\\\u0634\\\\u062e\\\\u0635 \\\\u0627\\\\u0644\\\\u0633\\\\u0644\\\\u064a\\\\u0645:\\\", \\\"  \\\\u2022 \\\\u0635\\\\u0627\\\\u0626\\\\u0645: 70-100 mg/dL\\\", \\\"  \\\\u2022 \\\\u0628\\\\u0639\\\\u062f \\\\u0627\\\\u0644\\\\u0623\\\\u0643\\\\u0644 \\\\u0628\\\\u0633\\\\u0627\\\\u0639\\\\u062a\\\\u064a\\\\u0646: \\\\u0623\\\\u0642\\\\u0644 \\\\u0645\\\\u0646 140 mg/dL\\\", \\\"\\\", \\\"\\\\u0644\\\\u0645\\\\u0631\\\\u064a\\\\u0636 \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631\\\\u064a:\\\", \\\"  \\\\u2022 \\\\u0635\\\\u0627\\\\u0626\\\\u0645: 80-130 mg/dL\\\", \\\"  \\\\u2022 \\\\u0628\\\\u0639\\\\u062f \\\\u0627\\\\u0644\\\\u0623\\\\u0643\\\\u0644: \\\\u0623\\\\u0642\\\\u0644 \\\\u0645\\\\u0646 180 mg/dL\\\", \\\"\\\", \\\"\\\\u2022 \\\\u0625\\\\u0630\\\\u0627 \\\\u0643\\\\u0627\\\\u0646 \\\\u0633\\\\u0643\\\\u0631\\\\u0643 \\\\u0645\\\\u0631\\\\u062a\\\\u0641\\\\u0639\\\\u060c \\\\u0627\\\\u0634\\\\u0631\\\\u0628 \\\\u0645\\\\u0627\\\\u0621 \\\\u0648\\\\u062a\\\\u062d\\\\u0631\\\\u0643 \\\\u0642\\\\u0644\\\\u064a\\\\u0644\\\\u0627\\\\u064b\\\", \\\"\\\\u2022 \\\\u0625\\\\u0630\\\\u0627 \\\\u0643\\\\u0627\\\\u0646 \\\\u0645\\\\u0646\\\\u062e\\\\u0641\\\\u0636\\\\u060c \\\\u062a\\\\u0646\\\\u0627\\\\u0648\\\\u0644 \\\\u0645\\\\u0635\\\\u062f\\\\u0631 \\\\u0633\\\\u0643\\\\u0631 \\\\u0633\\\\u0631\\\\u064a\\\\u0639 (\\\\u0639\\\\u0635\\\\u064a\\\\u0631 - \\\\u062d\\\\u0644\\\\u0648\\\\u0649)\\\"]\"', 'السكري', '\"[\\\"\\\\u0647\\\\u0648\\\", \\\"\\\\u0627\\\\u0644\\\\u0645\\\\u0639\\\\u062f\\\\u0644\\\", \\\"\\\\u0627\\\\u0644\\\\u0637\\\\u0628\\\\u064a\\\\u0639\\\\u064a\\\", \\\"\\\\u0644\\\\u0644\\\\u0633\\\\u0643\\\\u0631\\\\u061f\\\"]\"', 1, 'manual', 1, 0, 0, '2026-03-06 21:29:15', '2026-03-06 21:32:05'),
(2, 'ما هي أعراض ارتفاع الضغط؟', 'ما هي اعراض ارتفاع الضغط', 'غالباً لا تظهر أعراض واضحة لارتفاع الضغط، ولهذا يسمى \'القاتل الصامت\'. لكن في الحالات الشديدة قد تظهر بعض الأعراض.', '💓 أعراض ارتفاع الضغط', '\"[\\\"\\\\u2022 \\\\u0635\\\\u062f\\\\u0627\\\\u0639 \\\\u0634\\\\u062f\\\\u064a\\\\u062f\\\", \\\"\\\\u2022 \\\\u062f\\\\u0648\\\\u062e\\\\u0629\\\", \\\"\\\\u2022 \\\\u0632\\\\u063a\\\\u0644\\\\u0644\\\\u0629 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0639\\\\u064a\\\\u0646\\\", \\\"\\\\u2022 \\\\u0637\\\\u0646\\\\u064a\\\\u0646 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0623\\\\u0630\\\\u0646\\\", \\\"\\\\u2022 \\\\u0646\\\\u0632\\\\u064a\\\\u0641 \\\\u0623\\\\u0646\\\\u0641\\\", \\\"\\\\u2022 \\\\u062e\\\\u0641\\\\u0642\\\\u0627\\\\u0646\\\", \\\"\\\\u2022 \\\\u063a\\\\u062b\\\\u064a\\\\u0627\\\\u0646\\\"]\"', 'الضغط', '\"[\\\"\\\\u0647\\\\u064a\\\", \\\"\\\\u0623\\\\u0639\\\\u0631\\\\u0627\\\\u0636\\\", \\\"\\\\u0627\\\\u0631\\\\u062a\\\\u0641\\\\u0627\\\\u0639\\\", \\\"\\\\u0627\\\\u0644\\\\u0636\\\\u063a\\\\u0637\\\\u061f\\\"]\"', 1, 'manual', 0, 0, 0, '2026-03-06 21:29:15', '2026-03-06 21:29:15'),
(3, 'ما هي أعراض انخفاض الضغط؟', 'ما هي اعراض انخفاض الضغط', 'انخفاض الضغط قد يسبب أعراضاً مزعجة وتحتاج إلى متابعة.', '💓 أعراض انخفاض الضغط', '\"[\\\"\\\\u2022 \\\\u062f\\\\u0648\\\\u062e\\\\u0629\\\", \\\"\\\\u2022 \\\\u0625\\\\u063a\\\\u0645\\\\u0627\\\\u0621\\\", \\\"\\\\u2022 \\\\u062a\\\\u0634\\\\u0648\\\\u0634 \\\\u0627\\\\u0644\\\\u0631\\\\u0624\\\\u064a\\\\u0629\\\", \\\"\\\\u2022 \\\\u063a\\\\u062b\\\\u064a\\\\u0627\\\\u0646\\\", \\\"\\\\u2022 \\\\u062a\\\\u0639\\\\u0628 \\\\u0639\\\\u0627\\\\u0645\\\", \\\"\\\\u2022 \\\\u0639\\\\u0631\\\\u0642 \\\\u0628\\\\u0627\\\\u0631\\\\u062f\\\"]\"', 'الضغط', '\"[\\\"\\\\u0647\\\\u064a\\\", \\\"\\\\u0623\\\\u0639\\\\u0631\\\\u0627\\\\u0636\\\", \\\"\\\\u0627\\\\u0646\\\\u062e\\\\u0641\\\\u0627\\\\u0636\\\", \\\"\\\\u0627\\\\u0644\\\\u0636\\\\u063a\\\\u0637\\\\u061f\\\"]\"', 1, 'manual', 0, 0, 0, '2026-03-06 21:29:15', '2026-03-06 21:29:15'),
(4, 'ما هي استخدامات جلوكوفاج؟', 'ما هي استخدامات جلوكوفاج', 'جلوكوفاج (المادة الفعالة: ميتفورمين) هو دواء يستخدم لعلاج السكري من النوع الثاني.', '💊 دواء جلوكوفاج', '\"[\\\"\\\\u2022 \\\\u062e\\\\u0641\\\\u0636 \\\\u0645\\\\u0633\\\\u062a\\\\u0648\\\\u0649 \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u062f\\\\u0645\\\", \\\"\\\\u2022 \\\\u062a\\\\u062d\\\\u0633\\\\u064a\\\\u0646 \\\\u062d\\\\u0633\\\\u0627\\\\u0633\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u0623\\\\u0646\\\\u0633\\\\u0648\\\\u0644\\\\u064a\\\\u0646\\\", \\\"\\\\u2022 \\\\u062a\\\\u0642\\\\u0644\\\\u064a\\\\u0644 \\\\u0625\\\\u0646\\\\u062a\\\\u0627\\\\u062c \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631 \\\\u0645\\\\u0646 \\\\u0627\\\\u0644\\\\u0643\\\\u0628\\\\u062f\\\", \\\"\\\", \\\"\\\\u0627\\\\u0644\\\\u062c\\\\u0631\\\\u0639\\\\u0629 \\\\u0627\\\\u0644\\\\u0645\\\\u0639\\\\u062a\\\\u0627\\\\u062f\\\\u0629:\\\", \\\"\\\\u2022 500-2000 \\\\u0645\\\\u0644\\\\u063a \\\\u064a\\\\u0648\\\\u0645\\\\u064a\\\\u0627\\\\u064b\\\", \\\"\\\\u2022 \\\\u064a\\\\u0624\\\\u062e\\\\u0630 \\\\u0645\\\\u0639 \\\\u0627\\\\u0644\\\\u0623\\\\u0643\\\\u0644 \\\\u0644\\\\u062a\\\\u062c\\\\u0646\\\\u0628 \\\\u0627\\\\u0644\\\\u0622\\\\u062b\\\\u0627\\\\u0631 \\\\u0627\\\\u0644\\\\u062c\\\\u0627\\\\u0646\\\\u0628\\\\u064a\\\\u0629\\\", \\\"\\\", \\\"\\\\u0627\\\\u0644\\\\u0622\\\\u062b\\\\u0627\\\\u0631 \\\\u0627\\\\u0644\\\\u062c\\\\u0627\\\\u0646\\\\u0628\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u0634\\\\u0627\\\\u0626\\\\u0639\\\\u0629:\\\", \\\"\\\\u2022 \\\\u063a\\\\u062b\\\\u064a\\\\u0627\\\\u0646 (\\\\u0634\\\\u0627\\\\u0626\\\\u0639 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0628\\\\u062f\\\\u0627\\\\u064a\\\\u0629)\\\", \\\"\\\\u2022 \\\\u0625\\\\u0633\\\\u0647\\\\u0627\\\\u0644\\\", \\\"\\\\u2022 \\\\u0641\\\\u0642\\\\u062f\\\\u0627\\\\u0646 \\\\u0634\\\\u0647\\\\u064a\\\\u0629\\\"]\"', 'الأدوية', '\"[\\\"\\\\u0647\\\\u064a\\\", \\\"\\\\u0627\\\\u0633\\\\u062a\\\\u062e\\\\u062f\\\\u0627\\\\u0645\\\\u0627\\\\u062a\\\", \\\"\\\\u062c\\\\u0644\\\\u0648\\\\u0643\\\\u0648\\\\u0641\\\\u0627\\\\u062c\\\\u061f\\\"]\"', 1, 'manual', 0, 0, 0, '2026-03-06 21:29:15', '2026-03-06 21:29:15'),
