(16, 'بنكرياس ', 'بنكرياس', 'البنكرياس غدة مهمة في الجسم تقع خلف المعدة.', '🫁 معلومات عن البنكرياس', '\"[\\\"\\\\u2022 \\\\u0648\\\\u0638\\\\u0627\\\\u0626\\\\u0641\\\\u0647: \\\\u0625\\\\u0646\\\\u062a\\\\u0627\\\\u062c \\\\u0627\\\\u0644\\\\u0623\\\\u0646\\\\u0633\\\\u0648\\\\u0644\\\\u064a\\\\u0646 (\\\\u0644\\\\u062a\\\\u0646\\\\u0638\\\\u064a\\\\u0645 \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631) \\\\u0648\\\\u0625\\\\u0646\\\\u0632\\\\u064a\\\\u0645\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0647\\\\u0636\\\\u0645\\\", \\\"\\\\u2022 \\\\u0645\\\\u0634\\\\u0627\\\\u0643\\\\u0644\\\\u0647 \\\\u0627\\\\u0644\\\\u0634\\\\u0627\\\\u0626\\\\u0639\\\\u0629: \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0627\\\\u0644\\\\u0628\\\\u0646\\\\u0643\\\\u0631\\\\u064a\\\\u0627\\\\u0633\\\\u060c \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631\\\\u064a\\\\u060c \\\\u0623\\\\u0648\\\\u0631\\\\u0627\\\\u0645\\\", \\\"\\\\u2022 \\\\u0623\\\\u0639\\\\u0631\\\\u0627\\\\u0636 \\\\u0645\\\\u0634\\\\u0627\\\\u0643\\\\u0644\\\\u0647: \\\\u0623\\\\u0644\\\\u0645 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0628\\\\u0637\\\\u0646\\\\u060c \\\\u063a\\\\u062b\\\\u064a\\\\u0627\\\\u0646\\\\u060c \\\\u0641\\\\u0642\\\\u062f\\\\u0627\\\\u0646 \\\\u0648\\\\u0632\\\\u0646\\\", \\\"\\\\u2022 \\\\u0625\\\\u0630\\\\u0627 \\\\u0634\\\\u0639\\\\u0631\\\\u062a \\\\u0628\\\\u0623\\\\u0644\\\\u0645 \\\\u0634\\\\u062f\\\\u064a\\\\u062f \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0628\\\\u0637\\\\u0646\\\\u060c \\\\u0627\\\\u0633\\\\u062a\\\\u0634\\\\u0631 \\\\u0637\\\\u0628\\\\u064a\\\\u0628\\\\u0627\\\\u064b \\\\u0641\\\\u0648\\\\u0631\\\\u0627\\\\u064b\\\"]\"', 'عام', '\"[\\\"\\\\u0628\\\\u0646\\\\u0643\\\\u0631\\\\u064a\\\\u0627\\\\u0633\\\"]\"', 0.9, 'local', 1, 0, 0, '2026-03-07 16:21:55', '2026-03-07 16:21:55'),
(17, 'قلب', 'قلب', '[نبذة عن القلب]\n\nالقلب هو عضلة مجوفة بحجم قبضة اليد، تعمل كمضخة مركزية في جهاز الدوران. وظيفته الرئيسية هي ضخ الدم المحمل بالأكسجين والمواد الغذائية إلى جميع أنسجة الجسم عبر الشرايين، واستقبال الدم المحمل بثاني أكسيد الكربون من الأوردة لتنقيته في الرئتين.\n\n[النقاط]:\n• يقع في منتصف الصدر مائلاً قليلاً إلى اليسار.\n• ينبض حوالي 60-100 مرة في الدقيقة في الوضع الطبيعي.\n• يتكون من أربع حجرات: أذينين وبطينين.\n• يحصل على الأكسجين عبر الشرايين التاجية.\n• أي خلل في وظيفته (مثل عدم انتظام النبض أو ضعف الضخ) يحتاج إلى تقييم طبي فوري.', 'إجابة طبية', '\"[\\\"\\\\u2022 \\\\u064a\\\\u0642\\\\u0639 \\\\u0641\\\\u064a \\\\u0645\\\\u0646\\\\u062a\\\\u0635\\\\u0641 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0631 \\\\u0645\\\\u0627\\\\u0626\\\\u0644\\\\u0627\\\\u064b \\\\u0642\\\\u0644\\\\u064a\\\\u0644\\\\u0627\\\\u064b \\\\u0625\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u064a\\\\u0633\\\\u0627\\\\u0631.\\\", \\\"\\\\u2022 \\\\u064a\\\\u0646\\\\u0628\\\\u0636 \\\\u062d\\\\u0648\\\\u0627\\\\u0644\\\\u064a 60-100 \\\\u0645\\\\u0631\\\\u0629 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u062f\\\\u0642\\\\u064a\\\\u0642\\\\u0629 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0648\\\\u0636\\\\u0639 \\\\u0627\\\\u0644\\\\u0637\\\\u0628\\\\u064a\\\\u0639\\\\u064a.\\\", \\\"\\\\u2022 \\\\u064a\\\\u062a\\\\u0643\\\\u0648\\\\u0646 \\\\u0645\\\\u0646 \\\\u0623\\\\u0631\\\\u0628\\\\u0639 \\\\u062d\\\\u062c\\\\u0631\\\\u0627\\\\u062a: \\\\u0623\\\\u0630\\\\u064a\\\\u0646\\\\u064a\\\\u0646 \\\\u0648\\\\u0628\\\\u0637\\\\u064a\\\\u0646\\\\u064a\\\\u0646.\\\", \\\"\\\\u2022 \\\\u064a\\\\u062d\\\\u0635\\\\u0644 \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u0623\\\\u0643\\\\u0633\\\\u062c\\\\u064a\\\\u0646 \\\\u0639\\\\u0628\\\\u0631 \\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0627\\\\u064a\\\\u064a\\\\u0646 \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u0629.\\\", \\\"\\\\u2022 \\\\u0623\\\\u064a \\\\u062e\\\\u0644\\\\u0644 \\\\u0641\\\\u064a \\\\u0648\\\\u0638\\\\u064a\\\