u0644\\\\u0639\\\\u0644\\\\u0627\\\\u062c \\\\u0627\\\\u0631\\\\u062a\\\\u0641\\\\u0627\\\\u0639 \\\\u0636\\\\u063a\\\\u0637 \\\\u0627\\\\u0644\\\\u062f\\\\u0645 \\\\u0648\\\\u0627\\\\u0644\\\\u0630\\\\u0628\\\\u062d\\\\u0629 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0631\\\\u064a\\\\u0629.\\\", \\\"\\\\u2022 **\\\\u0646\\\\u062a\\\\u0631\\\\u0627\\\\u062a (Nitrates):** \\\\u0645\\\\u062b\\\\u0644 \\\\u0627\\\\u0644\\\\u0646\\\\u064a\\\\u062a\\\\u0631\\\\u0648\\\\u062c\\\\u0644\\\\u064a\\\\u0633\\\\u0631\\\\u064a\\\\u0646\\\\u060c \\\\u0644\\\\u062a\\\\u0648\\\\u0633\\\\u064a\\\\u0639 \\\\u0627\\\\u0644\\\\u0623\\\\u0648\\\\u0639\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u062f\\\\u0645\\\\u0648\\\\u064a\\\\u0629 \\\\u0648\\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u0630\\\\u0628\\\\u062d\\\\u0629 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0631\\\\u064a\\\\u0629.\\\", \\\"**\\\\u062a\\\\u0630\\\\u0643\\\\u064a\\\\u0631:** \\\\u0647\\\\u0630\\\\u0647 \\\\u0627\\\\u0644\\\\u0645\\\\u0639\\\\u0644\\\\u0648\\\\u0645\\\\u0627\\\\u062a \\\\u0644\\\\u0644\\\\u062a\\\\u0648\\\\u0639\\\\u064a\\\\u0629 \\\\u0641\\\\u0642\\\\u0637. \\\\u0644\\\\u0627 \\\\u062a\\\\u062a\\\\u0646\\\\u0627\\\\u0648\\\\u0644 \\\\u0623\\\\u064a \\\\u062f\\\\u0648\\\\u0627\\\\u0621 \\\\u0642\\\\u0644\\\\u0628\\\\u064a \\\\u062f\\\\u0648\\\\u0646 \\\\u0648\\\\u0635\\\\u0641\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0629\\\\u060c \\\\u0648\\\\u0644\\\\u0627 \\\\u062a\\\\u063a\\\\u064a\\\\u0631 \\\\u062c\\\\u0631\\\\u0639\\\\u062a\\\\u0643 \\\\u0623\\\\u0648 \\\\u062a\\\\u062a\\\\u0648\\\\u0642\\\\u0641 \\\\u0639\\\\u0646 \\\\u0627\\\\u0644\\\\u062f\\\\u0648\\\\u0627\\\\u0621 \\\\u062f\\\\u0648\\\\u0646 \\\\u0627\\\\u0633\\\\u062a\\\\u0634\\\\u0627\\\\u0631\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0628\\\\u0643.\\\"]\"', 'عام', '\"[\\\"\\\\u0627\\\\u0647\\\\u0645\\\", \\\"\\\\u0623\\\\u062f\\\\u0648\\\\u064a\\\\u0629\\\", \\\"\\\\u0627\\\\u0644\\\\u