(19, 'medical of haert', 'medical of haert', '[معلومات عامة عن القلب]\n\nالقلب هو عضو عضلي يعمل كمضخة لتوزيع الدم المحمل بالأكسجين والمواد الغذائية إلى جميع أنسجة الجسم عبر الدورة الدموية. يتكون من أربع حجرات (أذينان وبطينان) ويعمل بنظام كهربائي دقيق ينظم نبضاته.\n\n[النقاط]:\n• الوظيفة الأساسية: ضخ الدم عبر الجسم.\n• المكونات الرئيسية: العضلة القلبية، الصمامات (الأبهري، التاجي، ثلاثي الشرفات، الرئوي)، والشرايين التاجية التي تغذيه.\n• الأمراض الشائعة: تشمل أمراض الشرايين التاجية، وفشل القلب، واضطرابات النظم القلبي (الخفقان).\n• العناية بالقلب: تشمل اتباع نظام غذائي صحي، ممارسة الرياضة، تجنب التدخين، وإدارة الضغوط النفسية.', 'إجابة طبية', '\"[\\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0648\\\\u0638\\\\u064a\\\\u0641\\\\u0629 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0627\\\\u0633\\\\u064a\\\\u0629: \\\\u0636\\\\u062e \\\\u0627\\\\u0644\\\\u062f\\\\u0645 \\\\u0639\\\\u0628\\\\u0631 \\\\u0627\\\\u0644\\\\u062c\\\\u0633\\\\u0645.\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0645\\\\u0643\\\\u0648\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0631\\\\u0626\\\\u064a\\\\u0633\\\\u064a\\\\u0629: \\\\u0627\\\\u0644\\\\u0639\\\\u0636\\\\u0644\\\\u0629 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u064a\\\\u0629\\\\u060c \\\\u0627\\\\u0644\\\\u0635\\\\u0645\\\\u0627\\\\u0645\\\\u0627\\\\u062a (\\\\u0627\\\\u0644\\\\u0623\\\\u0628\\\\u0647\\\\u0631\\\\u064a\\\\u060c \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u060c \\\\u062b\\\\u0644\\\\u0627\\\\u062b\\\\u064a \\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0641\\\\u0627\\\\u062a\\\\u060c \\\\u0627\\\\u0644\\\\u0631\\\\u0626\\\\u0648\\\\u064a)\\\\u060c \\\\u0648\\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0627\\\\u064a\\\\u064a\\\\u0646 \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u062a\\\\u064a \\\\u062a\\\\u063a\\\\u0630\\\\u064a\\\\u0647.\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0623\\\\u0645\\\\u0631\\\\u0627\\\\u0636 \\\\u0627\\\\u0644\\\\u0634\\\\u0627\\\\u0626\\\\u0639\\\\u0629: \\\\u062a\\\\u0634\\\\u0645\\\\u0644 \\\\u0623\\\\u0645\\\\u0631\\\\u0627\\\\u0636 \\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0627\\\\u064a\\\\u064a\\\\u0646 \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u0629\\\\u060c \\\\u0648\\\\u0641\\\\u0634\\\\u0644 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u060c \\\\u0648\\\\u0627\\\\u0636\\\\u0637\\\\u0631\\\\u0627\\\\u0628\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0646\\\\u0638\\\\u0645 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u064a (\\\\u0627\\\\u0644\\\\u062e\\\\u0641\\\\u0642\\\\u0627\\\\u0646).\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0639\\\\u0646\\\\u0627\\\\u064a\\\\u0629 \\\\u0628\\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628: \\\\u062a\\\\u0634\\\\u0645\\\\u0644 \\\\u0627\\\\u062a\\\\u0628\\\\u0627\\\\u0639 \\\\u0646\\\\u0638\\\\u0627\\\\u0645 \\\\u063a\\\\u0630\\\\u0627\\\\u0626\\\\u064a \\\\u0635\\\\u062d\\\\u064a\\\\u060c \\\\u0645\\\\u0645\\\\u0627\\\\u0631\\\\u0633\\\\u0629 \\\\u0627\\\\u0644\\\\u0631\\\\u064a\\\\u0627\\\\u0636\\\\u0629\\\\u060c \\\\u062a\\\\u062c\\\\u0646\\\\u0628 \\\\u0627\\\\u0644\\\\u062a\\\\u062f\\\\u062e\\\\u064a\\\\u0646\\\\u060c \\\\u0648\\\\u0625\\\\u062f\\\\u0627\\\\u0631\\\\u0629 \\\\u0627\\\\u0644\\\\u0636\\\\u063a\\\\u0648\\\\u0637 \\\\u0627\\\\u0644\\\\u0646\\\\u0641\\\\u0633\\\\u064a\\\\u0629.\\\"]\"', 'عام', '\"[\\\"medical\\\", \\\"of\\\", \\\"haert\\\"]\"', 0.95, 'deepseek', 1, 0, 0, '2026-03-24 07:26:01', '2026-03-24 07:26:01'),
(20, 'مناخيري بتاكلنى وعيني تدمع و سنانى بتوجعنى', 'مناخيري بتاكلني وعيني تدمع و سناني بتوجعني', '[أعراض متعددة تحتاج تقييم طبي]:\nأعاني من ألم في الأسنان مع تدميع العينين، وهذه الأعراض قد تشير إلى مشكلة تحتاج فحصاً عاجلاً. ألم الأسنان الذي يمتد إلى العين يمكن أن يكون مرتبطاً بمشكلة في عصب السن أو التهاب في الجيوب الأنفية المجاورة.\n\n• **آلام الأسنان الممتدة للعين** قد تدل على التهاب عصب أو خراج.\n• **تدميع العين** المصاحب قد يكون رد فعل عصبي للألم أو علامة على التهاب الجيوب.\n• **يجب مراجعة طبيب الأسنان فوراً** للفحص وتحديد السبب.\n• **تجنب المسكنات القوية** دون وصفة طبية.\n• **استخدم كمادات باردة** على الخد لتخفيف الألم مؤقتاً.', 'إجابة طبية', '\"[\\\"\\\\u2022 **\\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0646\\\\u0627\\\\u0646 \\\\u0627\\\\u0644\\\\u0645\\\\u0645\\\\u062a\\\\u062f\\\\u0629 \\\\u0644\\\\u0644\\\\u0639\\\\u064a\\\\u0646** \\\\u0642\\\\u062f \\\\u062a\\\\u062f\\\\u0644 \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0639\\\\u0635\\\\u0628 \\\\u0623\\\\u0648 \\\\u062e\\\\u0631\\\\u0627\\\\u062c.\\\", \\\"\\\\u2022 **\\\\u062a\\\\u062f\\\\u0645\\\\u064a\\\\u0639 \\\\u0627\\\\u0644\\\\u0639\\\\u064a\\\\u0646** \\\\u0627\\\\u0644\\\\u0645\\\\u0635\\\\u0627\\\\u062d\\\\u0628 \\\\u0642\\\\u062f \\\\u064a\\\\u0643\\\\u0648\\\\u0646 \\\\u0631\\\\u062f \\\\u0641\\\\u0639\\\\u0644 \\\\u0639\\\\u0635\\\\u0628\\\\u064a \\\\u0644\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0623\\\\u0648 \\\\u0639\\\\u0644\\\\u0627\\\\u0645\\\\u0629 \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0627\\\\u0644\\\\u062c\\\\u064a\\\\u0648\\\\u0628.\\\", \\\"\\\\u2022 **\\\\u064a\\\\u062c\\\\u0628 \\\\u0645\\\\u0631\\\\u0627\\\\u062c\\\\u0639\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0628 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0646\\\\u0627\\\\u0646 \\\\u0641\\\\u0648\\\\u0631\\\\u0627\\\\u064b** \\\\u0644\\\\u0644\\\\u0641\\\\u062d\\\\u0635 \\\\u0648\\\\u062a\\\\u062d\\\\u062f\\\\u064a\\\\u062f \\\\u0627\\\\u0644\\\\u0633\\\\u0628\\\\u0628.\\\", \\\"\\\\u2022 **\\\\u062a\\\\u062c\\\\u0646\\\\u0628 \\\\u0627\\\\u0644\\\\u0645\\\\u0633\\\\u0643\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0642\\\\u0648\\\\u064a\\\\u0629** \\\\u062f\\\\u0648\\\\u0646 \\\\u0648\\\\u0635\\\\u0641\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0629.\\\", \\\"\\\\u2022 **\\\\u0627\\\\u0633\\\\u062a\\\\u062e\\\\u062f\\\\u0645 \\\\u0643\\\\u0645\\\\u0627\\\\u062f\\\\u0627\\\\u062a \\\\u0628\\\\u0627\\\\u0631\\\\u062f\\\\u0629** \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062e\\\\u062f \\\\u0644\\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0627\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0645\\\\u0624\\\\u0642\\\\u062a\\\\u0627\\\\u064b.\\\"]\"', 'عام', '\"[\\\"\\\\u0645\\\\u0646\\\\u0627\\\\u062e\\\\u064a\\\\u0631\\\\u064a\\\", \\\"\\\\u0628\\\\u062a\\\\u0627\\\\u0643\\\\u0644\\\\u0646\\\\u0649\\\", \\\"\\\\u0648\\\\u0639\\\\u064a\\\\u0646\\\\u064a\\\", \\\"\\\\u062a\\\\u062f\\\\u0645\\\\u0639\\\", \\\"\\\\u0633\\\\u0646\\\\u0627\\\\u0646\\\\u0649\\\"]\"', 0.95, 'deepseek', 1, 0, 0, '2026-04-13 07:22:57', '2026-04-13 07:22:57'),
(21, 'ايه احسن أدوية للبرد', 'ايه احسن ادويه للبرد', 'لا يوجد دواء واحد \"أفضل\" لعلاج البرد، حيث أن معظم نزلات البرد تسببها فيروسات وتزول من تلقاء نفسها. العلاج يركز على تخفيف الأعراض مثل الاحتقان والسعال والحمى. من المهم الراحة وشرب السوائل الدافئة بكثرة.', 'الرعاية المنزلية والعلاجات المساعدة لنزلات البرد', '\"[\\\"\\\\u2022  \\\\u0645\\\\u0633\\\\u0643\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0648\\\\u062e\\\\u0627\\\\u0641\\\\u0636\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u062d\\\\u0631\\\\u0627\\\\u0631\\\\u0629 \\\\u0645\\\\u062b\\\\u0644 \\\\u0627\\\\u0644\\\\u0628\\\\u0627\\\\u0631\\\\u0627\\\\u0633\\\\u064a\\\\u062a\\\\u0627\\\\u0645\\\\u0648\\\\u0644 \\\\u064a\\\\u0645\\\\u0643\\\\u0646 \\\\u0623\\\\u0646 \\\\u062a\\\\u0633\\\\u0627\\\\u0639\\\\u062f \\\\u0641\\\\u064a \\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0627\\\\u0639 \\\\u0648\\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u062c\\\\u0633\\\\u0645 \\\\u0648\\\\u0627\\\\u0644\\\\u062d\\\\u0645\\\\u0649.\\\", \\\"\\\\u2022  \\\\u064a\\\\u0645\\\\u0643\\\\u0646 \\\\u0644\\\\u0645\\\\u0632\\\\u064a\\\\u0644\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0627\\\\u062d\\\\u062a\\\\u0642\\\\u0627\\\\u0646 (\\\\u0639\\\\u0644\\\\u0649 \\\\u0634\\\\u0643\\\\u0644 \\\\u0623\\\\u0642\\\\u0631\\\\u0627\\\\u0635 \\\\u0623\\\\u0648 \\\\u0628\\\\u062e\\\\u0627\\\\u062e \\\\u0623\\\\u0646\\\\u0641\\\\u064a) \\\\u0623\\\\u0646 \\\\u062a\\\\u062e\\\\u0641\\\\u0641 \\\\u0627\\\\u0646\\\\u0633\\\\u062f\\\\u0627\\\\u062f \\\\u0627\\\\u0644\\\\u0623\\\\u0646\\\\u0641\\\\u060c \\\\u0648\\\\u0644\\\\u0643\\\\u0646 \\\\u064a\\\\u062c\\\\u0628 \\\\u0627\\\\u0633\\\\u062a\\\\u062e\\\\u062f\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u0628\\\\u062e\\\\u0627\\\\u062e \\\\u0644\\\\u0641\\\\u062a\\\\u0631\\\\u0629 \\\\u0645\\\\u062d\\\\u062f\\\\u0648\\\\u062f\\\\u0629.\\\", \\\"\\\\u2022  \\\\u062a\\\\u0633\\\\u0627\\\\u0639\\\\u062f \\\\u0627\\\\u0644\\\\u063a\\\\u0631\\\\u063a\\\\u0631\\\\u0629 \\\\u0628\\\\u0627\\\\u0644\\\\u0645\\\\u0627\\\\u0621 \\\\u0648\\\\u0627\\\\u0644\\\\u0645\\\\u0644\\\\u062d \\\\u0627\\\\u0644\\\\u062f\\\\u0627\\\\u0641\\\\u0626 \\\\u0639\\\\u0644\\\\u0649 \\\\u062a\\\\u0647\\\\u062f\\\\u0626\\\\u0629 \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0627\\\\u0644\\\\u062d\\\\u0644\\\\u0642.\\\", \\\"\\\\u2022  **\\\\u0627\\\\u0633\\\\u062a\\\\u0634\\\\u0631 \\\\u0627\\\\u0644\\\\u0635\\\\u064a\\\\u062f\\\\u0644\\\\u064a \\\\u0623\\\\u0648 \\\\u0627\\\\u0644\\\\u0637\\\\u0628\\\\u064a\\\\u0628 \\\\u062f\\\\u0627\\\\u0626\\\\u0645\\\\u064b\\\\u0627 \\\\u0642\\\\u0628\\\\u0644 \\\\u062a\\\\u0646\\\\u0627\\\\u0648\\\\u0644 \\\\u0623\\\\u064a \\\\u062f\\\\u0648\\\\u0627\\\\u0621\\\\u060c \\\\u062e\\\\u0627\\\\u0635\\\\u0629 \\\\u0644\\\\u0644\\\\u0623\\\\u0637\\\\u0641\\\\u0627\\\\u0644 \\\\u0623\\\\u0648 \\\\u0625\\\\u0630\\\\u0627 \\\\u0643\\\\u0646\\\\u062a \\\\u062a\\\\u0639\\\\u0627\\\\u0646\\\\u064a \\\\u0645\\\\u0646 \\\\u062d\\\\u0627\\\\u0644\\\\u0627\\\\u062a \\\\u0635\\\\u062d\\\\u064a\\\\u0629 \\\\u0623\\\\u062e\\\\u0631\\\\u0649.**\\\", \\\"\\\\u2022  **\\\\u0631\\\\u0627\\\\u062c\\\\u0639 \\\\u0627\\\\u0644\\\\u0637\\\\u0628\\\\u064a\\\\u0628 \\\\u0625\\\\u0630\\\\u0627 \\\\u0627\\\\u0633\\\\u062a\\\\u0645\\\\u0631\\\\u062a \\\\u0627\\\\u0644\\\\u0623\\\\u0639\\\\u0631\\\\u0627\\\\u0636 \\\\u0644\\\\u0623\\\\u0643\\\\u062b\\\\u0631 \\\\u0645\\\\u0646 \\\\u0623\\\\u0633\\\\u0628\\\\u0648\\\\u0639\\\\u060c \\\\u0623\\\\u0648 \\\\u0625\\\\u0630\\\\u0627 \\\\u0635\\\\u0627\\\\u062d\\\\u0628\\\\u0647\\\\u0627 \\\\u0636\\\\u064a\\\\u0642 \\\\u062a\\\\u0646\\\\u0641\\\\u0633 \\\\u0623\\\\u0648 \\\\u062d\\\\u0645\\\\u0649 \\\\u0639\\\\u0627\\\\u0644\\\\u064a\\\\u0629.**\\\"]\"', 'عام', '\"[\\\"\\\\u0627\\\\u064a\\\\u0647\\\", \\\"\\\\u0627\\\\u062d\\\\u0633\\\\u0646\\\", \\\"\\\\u0623\\\\u062f\\\\u0648\\\\u064a\\\\u0629\\\", \\\"\\\\u0644\\\\u0644\\\\u0628\\\\u0631\\\\u062f\\\"]\"', 0.95, 'deepseek', 1, 0, 0, '2026-04-18 11:51:34', '2026-04-18 11:51:34'),
(22, 'كم معدل الضغط الطبيعي للانسان؟', 'كم معدل الضغط الطبيعي للانسان', 'معدل ضغط الدم الطبيعي للبالغين هو أقل من 120/80 مم زئبق. الرقم العلوي (الانقباضي) يمثل ضغط الدم أثناء نبض القلب، والرقم السفلي (الانبساطي) يمثل الضغط بين النبضات.', '📏 المعدل الطبيعي للضغط', '[\"• الضغط المثالي: أقل من 120/80 مم زئبق.\", \"• ضغط مرتفع طفيف: 120-129 / أقل من 80.\", \"• ارتفاع الضغط المرحلة الأولى: 130-139 / 80-89.\", \"• ارتفاع الضغط المرحلة الثانية: 140 أو أعلى / 90 أو أعلى.\", \"• يجب قياس الضغط بانتظام بعد بلوغ سن 18.\"]', 'الضغط', '[\"معدل\", \"الضغط\", \"الطبيعي\", \"الانسان\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(23, 'ما هي أسباب فقر الدم؟', 'ما هي اسباب فقر الدم', 'فقر الدم (الأنيميا) يحدث عندما يكون عدد خلايا الدم الحمراء أو الهيموجلوبين أقل من الطبيعي. الأسباب الرئيسية تشمل نقص الحديد، نقص الفيتامينات، الأمراض المزمنة، أو فقدان الدم.', '🩸 أسباب فقر الدم', '[\"• نقص الحديد (الأكثر شيوعاً) بسبب سوء التغذية أو فقدان الدم.\", \"• نقص فيتامين ب12 أو حمض الفوليك.\", \"• أمراض مزمنة مثل الفشل الكلوي أو السرطان.\", \"• تكسر خلايا الدم الحمراء (مثل الأنيميا المنجلية).\", \"• فشل نخاع العظم في إنتاج خلايا الدم.\", \"• أعراضه: تعب، شحوب، دوخة، ضيق تنفس.\"]', 'أمراض الدم', '[\"اسباب\", \"فقر\", \"الدم\", \"الانيميا\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(24, 'ما هي أعراض جرثومة المعدة؟', 'ما هي اعراض جرثومة المعده', 'جرثومة المعدة (H. pylori) هي بكتيريا تصيب بطانة المعدة. كثير من المصابين لا تظهر عليهم أعراض، لكنها قد تسبب التهاباً أو قرحة في المعدة.', '🦠 أعراض جرثومة المعدة', '[\"• ألم أو حرقة في البطن (خاصة عندما تكون المعدة فارغة).\", \"• غثيان وفقدان شهية.\", \"• تجشؤ متكرر وانتفاخ.\", \"• فقدان وزن غير مبرر.\", \"• في الحالات المتقدمة: براز أسود أو قيء دموي (علامة نزيف).\", \"• يُشخص باختبار التنفس أو البراز أو المنظار.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"جرثومة\", \"المعدة\", \"H.pylori\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(25, 'ما هو علاج جرثومة المعدة؟', 'ما هو علاج جرثومة المعدة', 'يعالج جرثومة المعدة بمزيج من المضادات الحيوية وأدوية خفض الحموضة، لمدة 10-14 يوماً. من المهم إكمال الجرعة كاملة.', '💊 علاج جرثومة المعدة', '[\"• العلاج الثلاثي: مثبط مضخة البروتون + أموكسيسيلين + كلاريثروميسين.\", \"• العلاج الرباعي: يُستخدم إذا فشل الثلاثي أو كانت المقاومة عالية.\", \"• مضادات حيوية بديلة: ميترونيدازول أو تتراسايكلين.\", \"• تجنب مضادات الالتهاب غير الستيرويدية أثناء العلاج.\", \"• يُعاد الفحص بعد 4 أسابيع للتأكد من القضاء عليها.\"]', 'الجهاز الهضمي', '[\"علاج\", \"جرثومة\", \"المعدة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41');
INSERT INTO `chat_qa` (`id`, `question`, `normalized_question`, `answer`, `answer_title`, `bullets`, `category`, `keywords`, `confidence`, `source`, `usage_count`, `helpful_count`, `not_helpful_count`, `created_at`, `updated_at`) VALUES
(26, 'ما هي أعراض تكيس المبايض؟', 'ما هي اعراض تكيس المبايض', 'متلازمة تكيس المبايض (PCOS) هي اضطراب هرموني شائع عند النساء في سن الإنجاب، ويؤثر على الدورة الشهرية والخصوبة.', '🌸 أعراض تكيس المبايض', '[\"• عدم انتظام الدورة الشهرية أو انقطاعها.\", \"• زيادة نمو الشعر في الوجه والجسم (الشعرانية).\", \"• حب شباب شديد أو دهنية البشرة.\", \"• تساقط شعر الرأس.\", \"• زيادة الوزن أو صعوبة إنقاصه.\", \"• تكيسات صغيرة على المبيضين تُرى بالسونار.\", \"• قد يسبب مقاومة الأنسولين ومرض السكري.\"]', 'صحة المرأة', '[\"اعراض\", \"تكيس\", \"المبايض\", \"PCOS\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(27, 'ما هي أعراض الغدة الدرقية الخاملة؟', 'ما هي اعراض الغدة الدرقيه الخامله', 'قصور الغدة الدرقية (الخاملة) يحدث عندما لا تنتج الغدة ما يكفي من الهرمونات، مما يبطئ عمليات الأيض في الجسم.', '🦋 أعراض قصور الغدة الدرقية', '[\"• تعب وإرهاق شديد.\", \"• زيادة الوزن دون سبب واضح.\", \"• حساسية للبرد.\", \"• جفاف الجلد وتساقط الشعر.\", \"• إمساك.\", \"• آلام وضعف في العضلات.\", \"• بطء ضربات القلب.\", \"• اكتئاب وضعف التركيز.\", \"• علاجها: هرمون ليفوثيروكسين يومياً.\"]', 'الغدد الصماء', '[\"اعراض\", \"الغدة\", \"الدرقية\", \"الخاملة\", \"قصور\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(28, 'ما هي أعراض الغدة الدرقية النشطة؟', 'ما هي اعراض الغدة الدرقيه النشطه', 'فرط نشاط الغدة الدرقية يحدث عندما تنتج كمية زائدة من الهرمونات، مما يسرع عمليات الأيض.', '⚡ أعراض فرط الغدة الدرقية', '[\"• فقدان وزن غير مبرر مع شهية مفرطة.\", \"• سرعة ضربات القلب وخفقان.\", \"• عصبية، قلق، وأرق.\", \"• تعرق مفرط وحساسية للحرارة.\", \"• رعشة في الأصابع.\", \"• تضخم الغدة (الدراق الجحوظي).\", \"• جحوظ العينين في مرض جريفز.\", \"• إسهال وضعف عضلي.\"]', 'الغدد الصماء', '[\"اعراض\", \"الغدة\", \"الدرقية\", \"النشطة\", \"فرط\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(29, 'ما هي أعراض حصى الكلى؟', 'ما هي اعراض حصى الكلى', 'حصى الكلى هي تكتلات صلبة من المعادن والأملاح تتكون داخل الكلى. قد لا تسبب أعراضاً حتى تتحرك داخل الحالب.', '🪨 أعراض حصى الكلى', '[\"• ألم شديد في الخاصرة أو أسفل الظهر (مغص كلوي).\", \"• ألم يمتد إلى أسفل البطن والأربية.\", \"• ألم أو حرقة عند التبول.\", \"• بول أحمر أو بني أو عكر.\", \"• غثيان وقيء.\", \"• حاجة ملحة ومتكررة للتبول.\", \"• حمى وقشعريرة إذا صاحبها التهاب.\"]', 'المسالك البولية', '[\"اعراض\", \"حصى\", \"الكلى\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(30, 'ما هي أعراض التهاب المسالك البولية؟', 'ما هي اعراض التهاب المسالك البوليه', 'التهاب المسالك البولية (UTI) هو عدوى تصيب أي جزء من الجهاز البولي، وغالباً ما تكون في المثانة أو الإحليل.', '🚽 أعراض التهاب المسالك البولية', '[\"• حرقان وألم أثناء التبول.\", \"• كثرة التبول مع كميات قليلة.\", \"• رغبة ملحة ومفاجئة للتبول.\", \"• بول عكر أو كريه الرائحة أو به دم.\", \"• ألم في أسفل البطن (فوق العانة).\", \"• إذا وصلت للكلى: حمى، قشعريرة، ألم بالخاصرة.\", \"• يُعالج بالمضادات الحيوية وشرب الماء بكثرة.\"]', 'المسالك البولية', '[\"اعراض\", \"التهاب\", \"المسالك\", \"البولية\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(31, 'ما هي أعراض القولون العصبي؟', 'ما هي اعراض القولون العصبي', 'متلازمة القولون العصبي (IBS) هي اضطراب وظيفي مزمن في الأمعاء، يؤثر على حركتها وحساسيتها.', '😖 أعراض القولون العصبي', '[\"• ألم وتقلصات في البطن تتحسن بعد التبرز.\", \"• انتفاخ وغازات.\", \"• إمساك أو إسهال (أو تناوبهما).\", \"• تغير في قوام أو شكل البراز.\", \"• شعور بعدم إفراغ المستقيم بالكامل.\", \"• مخاط في البراز.\", \"• تزداد الأعراض بالتوتر أو أطعمة معينة.\", \"• لا يسبب نزيفاً أو فقدان وزن، وهما علامات خطر.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"القولون\", \"العصبي\", \"IBS\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(32, 'ما هو علاج القولون العصبي؟', 'ما هو علاج القولون العصبي', 'لا يوجد شفاء تام من القولون العصبي، لكن يمكن السيطرة على الأعراض بتغيير نمط الحياة والغذاء والأدوية.', '🩹 علاج القولون العصبي', '[\"• تغيير النظام الغذائي: تجنب المحفزات (الغازات، اللاكتوز).\", \"• اتباع نظام FODMAP منخفض قد يساعد.\", \"• زيادة الألياف تدريجياً للإمساك.\", \"• أدوية مضادة للتقلصات (مثل ميبيفرين).\", \"• مكملات ألياف أو ملينات للإمساك.\", \"• أدوية مضادة للإسهال (مثل لوبيراميد).\", \"• بروبيوتيك لتحسين البكتيريا المعوية.\", \"• إدارة التوتر والقلق (علاج نفسي، رياضة).\"]', 'الجهاز الهضمي', '[\"علاج\", \"القولون\", \"العصبي\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(33, 'ما هي أعراض فيروس كورونا الجديد؟', 'ما هي اعراض فيروس كورونا الجديد', 'تختلف أعراض كوفيد-19 من خفيفة إلى شديدة، وتظهر عادة بعد 2-14 يوماً من التعرض للفيروس.', '🦠 أعراض كوفيد-19', '[\"• حمى أو قشعريرة.\", \"• سعال جاف.\", \"• ضيق تنفس أو صعوبة في التنفس.\", \"• تعب وإرهاق.\", \"• فقدان حاسة التذوق أو الشم.\", \"• التهاب الحلق.\", \"• احتقان أو سيلان الأنف.\", \"• غثيان أو قيء أو إسهال.\", \"• في الحالات الشديدة: صعوبة تنفس حادة، ألم بالصدر.\", \"• الحصول على اللقاح يقلل من خطر المضاعفات.\"]', 'الأمراض المعدية', '[\"اعراض\", \"كورونا\", \"كوفيد\", \"COVID\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(34, 'ما هو علاج حب الشباب؟', 'ما هو علاج حب الشباب', 'علاج حب الشباب يعتمد على شدته. يبدأ عادة بالعلاجات الموضعية ثم الفموية للحالات المتوسطة والشديدة.', '🧴 علاج حب الشباب', '[\"• للبشرة الدهنية: غسولات تحتوي على حمض الساليسيليك.\", \"• حب الشباب الخفيف: بنزويل بيروكسايد موضعي.\", \"• الرتينوئيدات الموضعية (تريتينوين، أدابالين).\", \"• مضادات حيوية موضعية (كليندامايسين).\", \"• للحالات المتوسطة: مضادات حيوية فموية (دوكسيسايكلين).\", \"• للشديد المستعصي: إيزوتريتينوين (روأكيوتان) تحت إشراف طبي.\", \"• للحالات الهرمونية: حبوب منع الحمل أو سبيرونولاكتون.\", \"• تجنب عصر الحبوب لتجنب الندب.\"]', 'الأمراض الجلدية', '[\"علاج\", \"حب\", \"الشباب\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(35, 'ما هي أسباب آلام الظهر؟', 'ما هي اسباب آلام الظهر', 'آلام الظهر من أكثر الشكاوى شيوعاً. معظمها ناتج عن مشاكل ميكانيكية في العضلات أو الأربطة أو الفقرات.', '🦴 أسباب آلام الظهر', '[\"• إجهاد العضلات أو الأربطة (رفع ثقيل، حركة مفاجئة).\", \"• انزلاق غضروفي (ضغط على العصب).\", \"• تضيق القناة الشوكية.\", \"• خشونة المفاصل (التهاب المفصل العجزي الحرقفي).\", \"• هشاشة العظام وتكسير الفقرات.\", \"• وضعية جلوس أو وقوف خاطئة.\", \"• أسباب نادرة: ورم، عدوى.\", \"• غالباً يتحسن بالراحة والمسكنات والعلاج الطبيعي.\"]', 'العظام والمفاصل', '[\"اسباب\", \"آلام\", \"الظهر\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(36, 'ما هو علاج آلام الظهر؟', 'ما هو علاج آلام الظهر', 'العلاج يعتمد على السبب، لكن الخطوات الأولية تشمل الحفاظ على الحركة وتجنب الراحة التامة.', '🩺 علاج آلام الظهر', '[\"• مسكنات الألم ومضادات الالتهاب (إيبوبروفين).\", \"• كمادات دافئة أو باردة.\", \"• ممارسة النشاط الخفيف والمشي (الراحة التامة تضر).\", \"• العلاج الطبيعي (تمارين تقوية عضلات الجذع والبطن).\", \"• تصحيح وضعية الجلوس والوقوف.\", \"• فقدان الوزن الزائد.\", \"• في حالة الانزلاق الغضروفي: حقن الكورتيزون أو جراحة.\", \"• استشر طبيبك إذا كان الألم شديداً أو مع تنميل أو ضعف بالأطراف.\"]', 'العظام والمفاصل', '[\"علاج\", \"آلام\", \"الظهر\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(37, 'ما هي أعراض نقص الحديد؟', 'ما هي اعراض نقص الحديد', 'نقص الحديد هو السبب الأكثر شيوعاً لفقر الدم. الأعراض تظهر عندما يصبح النقص شديداً.', '🩸 أعراض نقص الحديد', '[\"• تعب شديد وإرهاق عام.\", \"• شحوب الجلد والأغشية المخاطية.\", \"• ضيق نفس مع مجهود بسيط.\", \"• تسارع ضربات القلب.\", \"• برودة الأيدي والأقدام.\", \"• هشاشة الأظافر وتقعرها (شكل ملعقة).\", \"• صداع ودوخة.\", \"• رغبة غريبة في أكل الثلج أو التراب (بيكا).\", \"• مصادره الغذائية: اللحوم الحمراء، السبانخ، العدس.\"]', 'التغذية', '[\"اعراض\", \"نقص\", \"الحديد\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(38, 'ما هي أعراض حساسية القمح؟', 'ما هي اعراض حساسيه القمح', 'حساسية القمح هي رد فعل مناعي ضد بروتينات القمح. تختلف عن مرض السيلياك والداء البطني.', '🌾 أعراض حساسية القمح', '[\"• تظهر بعد دقائق أو ساعات من تناول القمح.\", \"• طفح جلدي وحكة (شرى).\", \"• تورم الشفتين أو اللسان أو الوجه.\", \"• احتقان أنف وعطس.\", \"• غثيان، تقلصات بطن، إسهال.\", \"• صعوبة تنفس (ربو).\", \"• في الحالات الشديدة: صدمة تحسسية (أنافيلاكس).\", \"• العلاج: تجنب القمح نهائياً، ومضادات الهيستامين.\"]', 'الحساسية', '[\"اعراض\", \"حساسية\", \"القمح\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(39, 'ما هي أعراض السيلياك؟', 'ما هي اعراض السيلياك', 'الداء البطني (السيلياك) هو مرض مناعي ذاتي يهاجم الأمعاء الدقيقة عند تناول الجلوتين (بروتين في القمح والشعير والجاودار).', '🌾 أعراض السيلياك', '[\"• إسهال مزمن أو إمساك.\", \"• انتفاخ وغازات وآلام بطن.\", \"• فقدان وزن وسوء تغذية.\", \"• تعب شديد بسبب فقر الدم.\", \"• طفح جلدي (التهاب الجلد الحلئي).\", \"• قرح فموية.\", \"• آلام عظام ومفاصل.\", \"• تأخر النمو عند الأطفال.\", \"• العلاج الوحيد هو تجنب الجلوتين مدى الحياة.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"السيلياك\", \"الداء\", \"البطني\", \"جلوتين\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(40, 'ما هي أعراض التهاب الزائدة الدودية؟', 'ما هي اعراض التهاب الزائدة الدوديه', 'التهاب الزائدة الدودية حالة طبية طارئة تستوجب تدخلاً جراحياً سريعاً.', '⚠️ أعراض التهاب الزائدة الدودية', '[\"• ألم يبدأ حول السرة ثم ينتقل إلى أسفل البطن الأيمن.\", \"• يزداد الألم بالسعال أو المشي أو الضغط على المنطقة.\", \"• فقدان شهية.\", \"• غثيان وقيء.\", \"• حمى خفيفة.\", \"• إمساك أو إسهال.\", \"• لا تحاول تناول مسكنات قوية فقد تخفي الأعراض.\", \"• إذا شعرت بهذه الأعراض، اذهب للمستشفى فوراً.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"التهاب\", \"الزائدة\", \"الدودية\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(41, 'ما هي أعراض السكري عند الأطفال؟', 'ما هي اعراض السكري عند الاطفال', 'النوع الأول من السكري هو الأكثر شيوعاً عند الأطفال، ويمكن أن تظهر أعراضه فجأة وبشكل حاد.', '👶 أعراض سكري الأطفال', '[\"• العطش الشديد وكثرة التبول (قد يتبول الطفل في الفراش).\", \"• الجوع المفرط.\", \"• فقدان وزن غير مبرر.\", \"• تعب وضعف عام.\", \"• تشوش الرؤية.\", \"• التهابات متكررة (جلدية أو بولية).\", \"• رائحة نفس تشبه الأسيتون (في الحالات المتقدمة).\", \"• إذا تركت دون علاج، قد تؤدي إلى غيبوبة سكرية.\", \"• يجب قياس السكر فوراً عند الشك.\"]', 'السكري', '[\"اعراض\", \"السكري\", \"الأطفال\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(42, 'كم مرة يجب قياس الضغط؟', 'كم مره يجب قياس الضغط', 'تكرار قياس الضغط يعتمد على عمرك وحالتك الصحية. للبالغين الأصحاء، مرة كل سنتين كافية، ولكن لمرضى الضغط، يجب قياسه بشكل متكرر.', '📏 تكرار قياس الضغط', '[\"• للبالغين الأصحاء (18-40 سنة): مرة كل 2-5 سنوات.\", \"• لمن هم فوق 40 أو لديهم عوامل خطر: مرة كل سنة.\", \"• لمرضى ارتفاع الضغط: يومياً (مرتين صباحاً ومساءً).\", \"• عند تغيير الدواء: قياس مرتين يومياً لمدة أسبوع.\", \"• يفضل القياس في نفس الأوقات يومياً، قبل الأكل وبعد الراحة.\", \"• تجنب القياس بعد الكافيين أو التدخين مباشرة.\"]', 'الضغط', '[\"كم\", \"مرة\", \"قياس\", \"الضغط\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(43, 'ما هو علاج الأنيميا؟', 'ما هو علاج الانيميا', 'علاج الأنيميا يعتمد على نوعها وسببها. الأكثر شيوعاً هو أنيميا نقص الحديد.', '💊 علاج فقر الدم', '[\"• أنيميا نقص الحديد: مكملات الحديد بالفم (كبريتات الحديدوز).\", \"• يُفضل تناولها مع فيتامين سي لامتصاص أفضل.\", \"• تظهر نتائج تحسن الدم بعد 2-4 أسابيع.\", \"• أنيميا نقص ب12: حقن أو أقراص فيتامين ب12.\", \"• أنيميا نقص الفوليك: مكملات حمض الفوليك.\", \"• أنيميا الأمراض المزمنة: علاج المرض الأساسي.\", \"• الأنيميا الشديدة أو الناتجة عن نزيف: نقل دم.\", \"• الإكثار من الأطعمة الغنية بالحديد: كبد، لحم أحمر، سبانخ.\"]', 'أمراض الدم', '[\"علاج\", \"الانيميا\", \"فقر\", \"الدم\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(44, 'هل المشي ينزل الضغط؟', 'هل المشي ينزل الضغط', 'نعم، المشي بانتظام يساعد في خفض ضغط الدم المرتفع وتحسين صحة القلب والأوعية الدموية.', '🚶 المشي وخفض الضغط', '[\"• المشي لمدة 30 دقيقة يومياً يمكن أن يخفض الضغط بمقدار 4-9 مم زئبق.\", \"• يفضل المشي السريع (الذي يزيد من سرعة التنفس والنبض).\", \"• يساعد في فقدان الوزن، وهو عامل مهم في السيطرة على الضغط.\", \"• يقلل من التوتر والضغط النفسي.\", \"• استمر لمدة 5 أيام على الأقل في الأسبوع.\", \"• إذا كنت مصاباً بارتفاع ضغط شديد، استشر طبيبك قبل البدء.\"]', 'الضغط', '[\"هل\", \"المشي\", \"ينزل\", \"الضغط\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(45, 'ما هي أعراض فقر الدم المنجلي؟', 'ما هي اعراض فقر الدم المنجلي', 'فقر الدم المنجلي هو مرض وراثي يتسبب في تشوه خلايا الدم الحمراء إلى شكل الهلال، مما يؤدي إلى انسداد الأوعية الدموية.', '🩸 أعراض الأنيميا المنجلية', '[\"• نوبات ألم حادة (أزمة منجلية) في العظام والبطن والصدر.\", \"• تورم مؤلم في اليدين والقدمين (عند الرضع).\", \"• تعب وشحوب بسبب فقر الدم المزمن.\", \"• اصفرار العينين والجلد (اليرقان).\", \"• تأخر النمو عند الأطفال.\", \"• تكرار العدوى (خاصة الالتهاب الرئوي).\", \"• متلازمة الصدر الحادة (ألم صدر، حمى، صعوبة تنفس).\", \"• الوقاية: شرب الماء، تجنب البرد والجهد الزائد، حمض الفوليك.\"]', 'أمراض الدم', '[\"اعراض\", \"فقر\", \"الدم\", \"المنجلي\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(46, 'ما هي أسباب الكحة الجافة؟', 'ما هي اسباب الكحه الجافه', 'الكحة الجافة هي كحة غير مصاحبة ببلغم. أسبابها عديدة من الحساسية إلى الأمراض الرئوية.', '🫁 أسباب الكحة الجافة', '[\"• حساسية الأنف (التنقيط الأنفي الخلفي).\", \"• الربو (خاصة ربو الكحة).\", \"• ارتجاع المرىء.\", \"• الأدوية: مثبطات الإنزيم المحول للأنجيوتنسين (للضغط).\", \"• العدوى الفيروسية بعد الشفاء من البرد.\", \"• السعال الديكي.\", \"• قصور القلب.\", \"• إذا استمرت أكثر من 3 أسابيع، راجع الطبيب.\"]', 'أمراض الجهاز التنفسي', '[\"اسباب\", \"الكحة\", \"الجافة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(47, 'ما هو علاج الحموضة؟', 'ما هو علاج الحموضه', 'حموضة المعدة (حرقة الفؤاد) تحدث عندما ترتد الأحماض إلى المرىء. يمكن علاجها بتغيير نمط الحياة والأدوية.', '🔥 علاج الحموضة', '[\"• مضادات الحموضة الفورية (مالوكس، ريني) للتخفيف السريع.\", \"• مثبطات مضخة البروتون (أوميبرازول، إيزوميبرازول) لخفض الحموضة.\", \"• حاصرات الهيستامين 2 (فاموتيدين).\", \"• تجنب الأطعمة المسببة: الحار، الدهني، الحمضيات، القهوة.\", \"• لا تنم بعد الأكل مباشرة (انتظر 2-3 ساعات).\", \"• ارفع رأس السرير 15-20 سم.\", \"• فقدان الوزن وتجنب التدخين.\"]', 'الجهاز الهضمي', '[\"علاج\", \"الحموضة\", \"حرقة\", \"المعدة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(48, 'ما هي أعراض ارتفاع الكوليسترول؟', 'ما هي اعراض ارتفاع الكوليسترول', 'ارتفاع الكوليسترول لا تظهر له أعراض واضحة. يُكتشف عادةً بفحص الدم، وقد تؤدي مضاعفاته إلى ظهور أعراض.', '📊 أعراض الكوليسترول المرتفع', '[\"• لا توجد أعراض مباشرة لارتفاع الكوليسترول نفسه.\", \"• لكن مضاعفاته (تصلب الشرايين) قد تسبب:\", \"  - ألم في الصدر (ذبحة صدرية).\", \"  - ضيق في الساقين عند المشي (العرج المتقطع).\", \"  - ظهور أورام صفراء على الجلد أو حول العينين.\", \"  - جلطات دماغية أو قلبية.\", \"• الفحص الدوري للكوليسترول ضروري بعد سن 20.\", \"• العلاج: غذاء صحي، رياضة، وستاتينات.\"]', 'الكوليسترول', '[\"اعراض\", \"ارتفاع\", \"الكوليسترول\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(49, 'ما هي أعراض الربو؟', 'ما هي اعراض الربو', 'الربو هو مرض تنفسي مزمن يسبب التهاب وتضيق الشعب الهوائية، مما يؤدي إلى نوبات متكررة من صعوبة التنفس.', '😤 أعراض الربو', '[\"• صعوبة في التنفس (ضيق نفس).\", \"• أزيز أو صفير أثناء التنفس (خاصة الزفير).\", \"• كحة جافة، تزداد ليلاً أو مع النشاط.\", \"• ضيق في الصدر.\", \"• النوبات قد تحدث بسبب الحساسية، البرد، الجهد، أو التوتر.\", \"• أعراض الطوارئ: شفاه زرقاء، عدم القدرة على الكلام، سرعة تنفس شديدة.\", \"• يُعالج بموسعات الشعب (مثل فينتولين) والكورتيزون المستنشَق.\"]', 'أمراض الجهاز التنفسي', '[\"اعراض\", \"الربو\", \"أزيز\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(50, 'ما هي أعراض دوالي الساقين؟', 'ما هي اعراض دوالي الساقين', 'الدوالي هي أوردة متضخمة وملتوية تظهر تحت الجلد، تحدث بسبب ضعف صمامات الأوردة.', '🦵 أعراض دوالي الساقين', '[\"• ظهور أوردة زرقاء أو بنفسجية بارزة.\", \"• ألم أو ثقل في الساقين.\", \"• تورم في الكاحلين والقدمين.\", \"• حكة حول الوريد.\", \"• تشنجات عضلية ليلاً.\", \"• تغير لون الجلد (بني) في الحالات المتقدمة.\", \"• قروح جلدية بالقرب من الكاحل (في المراحل المتأخرة).\", \"• الوقاية: تجنب الوقوف الطويل، رفع القدمين، لبس جوارب ضاغطة.\"]', 'أمراض الأوعية الدموية', '[\"اعراض\", \"دوالي\", \"الساقين\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(51, 'ما هي أعراض التهاب المفاصل الروماتويدي؟', 'ما هي اعراض التهاب المفاصل الروماتويدي', 'الروماتويد هو مرض مناعي ذاتي يسبب التهاباً مزمناً في المفاصل، ويمكن أن يؤثر أيضاً على أعضاء أخرى.', '🦴 أعراض الروماتويد', '[\"• ألم وتيبس في المفاصل (خاصة في الصباح لأكثر من 30 دقيقة).\", \"• تورم واحمرار ودفء في المفاصل.\", \"• يصيب عادةً المفاصل الصغيرة (الرسغ، الأصابع، القدمين).\", \"• يكون متماثلاً (نفس المفصل في الجانبين).\", \"• تعب شديد وحمى خفيفة.\", \"• فقدان الوزن.\", \"• عقيدات روماتويدية تحت الجلد.\", \"• العلاج المبكر مهم لتجنب تشوه المفاصل.\"]', 'العظام والمفاصل', '[\"اعراض\", \"التهاب\", \"المفاصل\", \"الروماتويدي\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(52, 'ما هي أعراض هشاشة العظام؟', 'ما هي اعراض هشاشة العظام', 'هشاشة العظام مرض صامت لا تظهر له أعراض حتى يحدث كسر. تعتبر هشاشة العظام من أكثر الأمراض شيوعاً عند كبار السن خاصة النساء.', '🦴 أعراض هشاشة العظام', '[\"• لا تظهر أعراض في المراحل المبكرة.\", \"• عندما تصبح العظام ضعيفة، قد تسبب:\", \"  - آلام ظهر مفاجئة وشديدة بسبب كسر الفقرة.\", \"  - فقدان الطول بمرور الوقت.\", \"  - انحناء الظهر (الحدبة).\", \"  - كسور سهلة من سقوط بسيط أو حتى عطس.\", \"• عوامل الخطر: سن متقدم، نساء بعد انقطاع الطمث، نقص كالسيوم وفيتامين د.\", \"• الوقاية: غذاء غني بالكالسيوم، فيتامين د، ورياضة حمل الأثقال.\"]', 'العظام والمفاصل', '[\"اعراض\", \"هشاشة\", \"العظام\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(53, 'ما هي أعراض الجيوب الأنفية؟', 'ما هي اعراض الجيوب الانفيه', 'التهاب الجيوب الأنفية هو التهاب يصيب التجاويف المملوءة بالهواء حول الأنف والعينين والجبهة.', '🤧 أعراض الجيوب الأنفية', '[\"• إفرازات أنفية سميكة صفراء أو خضراء.\", \"• احتقان أنف وصعوبة في التنفس.\", \"• ألم وضغط حول العينين أو الخدين أو الجبهة.\", \"• صداع خلف العين.\", \"• ألم في الأسنان العلوية.\", \"• تخفيف حاسة الشم والتذوق.\", \"• كحة تزداد ليلاً.\", \"• رائحة نفس كريهة.\", \"• الحالات الحادة تستجيب للمضادات الحيوية ومزيلات الاحتقان.\"]', 'أمراض الجهاز التنفسي', '[\"اعراض\", \"الجيوب\", \"الأنفية\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(54, 'ما هي أعراض تكيس الثدي؟', 'ما هي اعراض تكيس الثدي', 'التكيسات الثديية هي أكياس مليئة بالسوائل، وهي حميدة وشائعة لدى النساء في سن 35-50.', '🎀 أعراض تكيسات الثدي', '[\"• كتلة أو كتل ناعمة وسهلة الحركة تحت الجلد.\", \"• تزيد في الحجم وتصبح مؤلمة قبل الدورة الشهرية.\", \"• تختفي أو تصغر بعد الدورة.\", \"• قد تكون مؤلمة عند اللمس.\", \"• في السونار تظهر كأكياس بدلاً من كتل صلبة.\", \"• معظمها لا يحتاج علاجاً، لكن إذا كانت كبيرة ومؤلمة يمكن سحب السائل بإبرة.\", \"• إذا كانت الكتلة صلبة أو غير منتظمة أو عند امرأة فوق 40، يجب فحصها بالماموجرام.\"]', 'صحة المرأة', '[\"اعراض\", \"تكيس\", \"الثدي\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(55, 'ما هي أعراض انقطاع الطمث؟', 'ما هي اعراض انقطاع الطمث', 'انقطاع الطمث هو توقف الدورة الشهرية لمدة 12 شهراً متتالياً. تحدث أعراضه بسبب انخفاض الهرمونات الأنثوية.', '🌸 أعراض سن اليأس', '[\"• عدم انتظام الدورة ثم توقفها.\", \"• الهبات الساخنة (الشعور بحرارة مفاجئة في الوجه والرقبة).\", \"• تعرق ليلي.\", \"• جفاف المهبل وألم أثناء الجماع.\", \"• اضطرابات النوم.\", \"• تقلبات مزاجية واكتئاب.\", \"• زيادة الوزن وبطء الأيض.\", \"• ترقق العظام وهشاشتها.\", \"• العلاج الهرموني قد يخفف الأعراض لكن له مخاطره.\"]', 'صحة المرأة', '[\"اعراض\", \"انقطاع\", \"الطمث\", \"سن\", \"اليأس\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(56, 'ما هي أعراض البروستاتا؟', 'ما هي اعراض البروستاتا', 'تضخم البروستاتا الحميد شائع جداً عند الرجال فوق سن الخمسين. قد يسبب أعراضاً بولية مزعجة.', '🧔 أعراض تضخم البروستاتا', '[\"• كثرة التبول (خاصة في الليل).\", \"• صعوبة في بدء التبول.\", \"• ضعف تيار البول أو تقطعه.\", \"• شعور بعدم إفراغ المثانة بالكامل.\", \"• إلحاح مفاجئ للتبول.\", \"• بالتنقيط بعد الانتهاء.\", \"• في الحالات المتقدمة: احتباس بول، دم في البول.\", \"• استشر طبيب المسالك لتجنب مضاعفات على الكلى.\"]', 'صحة الرجل', '[\"اعراض\", \"البروستاتا\", \"تضخم\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(57, 'ما هي أعراض مرض باركنسون؟', 'ما هي اعراض مرض باركنسون', 'الشلل الرعاش (باركنسون) هو مرض عصبي تقدمي يؤثر على الحركة. يبدأ عادة بعد سن 60.', '🧠 أعراض باركنسون', '[\"• رعشة في اليد أو الأصابع أثناء الراحة.\", \"• بطء الحركة (تباطؤ الأداء اليومي).\", \"• تيبس العضلات (صلابة في الأطراف أو الجذع).\", \"• ضعف التوازن وصعوبة المشي.\", \"• خطوات قصيرة ولصق القدم بالأرض.\", \"• تعابير وجه قليلة (وجه قناع).\", \"• كلام ناعم أو مونوتون.\", \"• خط يد صغير (ميكروجرافيا).\", \"• لا يوجد شفاء، لكن الأدوية (ليفودوبا) تحسن الأعراض.\"]', 'الأمراض العصبية', '[\"اعراض\", \"باركنسون\", \"الشلل\", \"الرعاش\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(58, 'ما هي أعراض الجلطة الدماغية؟', 'ما هي اعراض الجلطه الدماغيه', 'الجلطة الدماغية (السكتة) تحدث عندما ينقطع تدفق الدم إلى جزء من الدماغ. التعرف المبكر عليها قد ينقذ حياة.', '🚨 أعراض السكتة الدماغية', '[\"• استخدم قاعدة FAST:\", \"  - F (الوجه): تدلى جانب من الوجه عند الابتسام.\", \"  - A (الذراع): ضعف أو تنميل في ذراع واحدة.\", \"  - S (الكلام): كلام غير مفهوم أو صعوبة في التحدث.\", \"  - T (الوقت): اتصل بالإسعاف فوراً.\", \"• أعراض أخرى: تنميل نصف الجسم، دوخة شديدة، صداع مفاجئ، تشوش الرؤية.\", \"• كل دقيقة مهمة؛ العلاج المبكر يقلل العجز.\", \"• الوقاية: التحكم بالضغط والسكر والكوليسترول.\"]', 'الأمراض العصبية', '[\"اعراض\", \"الجلطة\", \"الدماغية\", \"السكتة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(59, 'ما هي أعراض حصوة المرارة؟', 'ما هي اعراض حصوه المراره', 'حصوات المرارة هي تكتلات صلبة تتكون داخل المرارة. كثير من الناس لديهم حصوات بدون أعراض.', '🪨 أعراض حصى المرارة', '[\"• ألم مفاجئ وشديد في الجزء العلوي الأيمن من البطن.\", \"• ألم يمتد إلى الكتف الأيمن أو الظهر.\", \"• ألم بعد تناول وجبة دسمة (خاصة الدهون).\", \"• غثيان وقيء.\", \"• في حال انسداد القناة: حمى، يرقان (اصفرار الجلد)، بول داكن.\", \"• الحصوات الصامتة لا تحتاج علاجاً.\", \"• إذا تكررت النوبات، قد تحتاج لإزالة المرارة (استئصال بالمنظار).\"]', 'الجهاز الهضمي', '[\"اعراض\", \"حصوة\", \"المرارة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(60, 'ما هي أعراض تمزق الأربطة؟', 'ما هي اعراض تمزق الاربطة', 'تمزق الأربطة (خاصة في الكاحل أو الركبة) يحدث غالباً أثناء الرياضة أو الحركات المفاجئة.', '🦵 أعراض تمزق الأربطة', '[\"• صوت فرقعة لحظة الإصابة.\", \"• ألم شديد ومفاجئ.\", \"• تورم كبير في المفصل خلال ساعات.\", \"• كدمات حول المنطقة.\", \"• عدم استقرار المفصل (شعور بأن الركبة ستخرج من مكانها).\", \"• صعوبة تحريك المفصل أو المشي.\", \"• يختلف العلاج من راحة وجبس إلى جراحة حسب درجة التمزق.\", \"• اسعاف أولي: راحة، ثلج، ضغط، رفع.\"]', 'العظام والمفاصل', '[\"اعراض\", \"تمزق\", \"الأربطة\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(61, 'ما هي أعراض فتق البطن؟', 'ما هي اعراض فتق البطن', 'الفتق هو بروز عضو أو نسيج دهني من خلال نقطة ضعيفة في جدار البطن.', '🩻 أعراض الفتق', '[\"• انتفاخ أو كتلة واضحة تحت جلد البطن أو الأربية.\", \"• تزداد الكتلة عند الوقوف أو السعال أو رفع شيء.\", \"• ألم أو شعور بثقل في المنطقة.\", \"• قد تختفي الكتلة عند الاستلقاء.\", \"• الفتق المحتجز (لا يمكن رده) يكون مؤلماً.\", \"• الفتق المختنق (انقطاع الدم) حالة طوارئ: ألم شديد، غثيان، قيء، انتفاخ أحمر.\", \"• العلاج هو الجراحة.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"فتق\", \"البطن\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(62, 'ما هي أعراض سرطان الثدي؟', 'ما هي اعراض سرطان الثدي', 'الكشف المبكر عن سرطان الثدي يزيد من فرص العلاج. يجب على كل امرأة أن تعرف شكل ثدييها وتلاحظ أي تغير.', '🎗️ أعراض سرطان الثدي', '[\"• كتلة صلبة غير مؤلمة في الثدي أو تحت الإبط.\", \"• تغير في حجم أو شكل الثدي.\", \"• تنقير في الجلد (مثل قشر البرتقال).\", \"• احمرار أو تقشر جلد الثدي.\", \"• إفرازات من الحلمة (خاصة دموية).\", \"• انقلاب الحلمة إلى الداخل.\", \"• ألم في الثدي لا يزول.\", \"• ليس كل كتلة سرطانية؛ لكن كل كتلة تستحق الفحص.\", \"• الماموجرام كل سنتين بعد سن 40.\"]', 'الأورام', '[\"اعراض\", \"سرطان\", \"الثدي\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(63, 'ما هي أعراض القولون؟ (السرطان)', 'ما هي اعراض القولون سرطان', 'سرطان القولون من الأورام الشائعة لكن يمكن الوقاية منه بالكشف المبكر. الأعراض قد لا تظهر في المراحل المبكرة.', '⚠️ أعراض سرطان القولون', '[\"• تغير في عادات التبرز (إسهال أو إمساك لمدة تزيد عن 4 أسابيع).\", \"• نزيف من المستقيم أو دم في البراز.\", \"• ألم أو غازات أو تقلصات مستمرة بالبطن.\", \"• شعور بأن الأمعاء لا تفرغ بالكامل.\", \"• ضعف وتعب وفقر دم بدون سبب.\", \"• فقدان وزن غير مبرر.\", \"• الفحص الدوري بالمنظار بعد سن 45 ينقذ الأرواح.\", \"• لا تتردد في إجراء الفحص إذا كان في العائلة تاريخ للمرض.\"]', 'الأورام', '[\"اعراض\", \"سرطان\", \"القولون\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(64, 'ما هي أعراض الارتجاع المريئي؟', 'ما هي اعراض الارتجاع المريئي', 'الارتجاع المريئي (GERD) هو عودة حمض المعدة إلى المريء بشكل مزمن، يسبب أعراضاً مزعجة.', '🔥 أعراض الارتجاع المريئي', '[\"• حرقة في الصدر (خلف عظمة الصدر) تزداد بعد الأكل أو عند الاستلقاء.\", \"• ارتجاع طعم حامض أو مر إلى الحلق.\", \"• ألم أو صعوبة في البلع.\", \"• كحة جافة مزمنة، خاصة ليلاً.\", \"• التهاب الحلق وبحة صوت.\", \"• الشعور بكتلة في الحلق.\", \"• مضاعفاته: التهاب المريء، تضيق، مريء باريت (تسرطن).\", \"• العلاج: مثبطات مضخة البروتون، تغيير نمط الحياة.\"]', 'الجهاز الهضمي', '[\"اعراض\", \"الارتجاع\", \"المريئي\", \"GERD\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(65, 'ما هي أعراض الغدة النخامية؟', 'ما هي اعراض الغده النخاميه', 'أورام الغدة النخامية (غالباً حميدة) يمكن أن تسبب أعراضاً بسبب ضغطها على الأعصاب أو إفرازها لهرمونات زائدة.', '🧠 أعراض أورام الغدة النخامية', '[\"• صداع شديد.\", \"• مشاكل في الرؤية (فقدان الرؤية الجانبية).\", \"• اضطرابات هرمونية:\", \"  - إفراز زائد لهرمون النمو (ضخامة الأطراف).\", \"  - إفراز برولاكتين (إدرار حليب غير طبيعي، اضطراب دورة).\", \"  - مرض كوشينغ (زيادة كورتيزول: سمنة مركزية، خطوط أرجوانية).\", \"• قصور الغدة: تعب، ضغط منخفض.\", \"• التشخيص بالرنين المغناطيسي وقياس الهرمونات.\"]', 'الغدد الصماء', '[\"اعراض\", \"الغدة\", \"النخامية\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(66, 'ما هي فوائد زيت الزيتون؟', 'ما هي فوائد زيت الزيتون', 'زيت الزيتون البكر الممتاز هو أساس حمية البحر المتوسط وله فوائد صحية عديدة.', '🫒 فوائد زيت الزيتون', '[\"• غني بمضادات الأكسدة التي تحمي الخلايا.\", \"• يقلل الالتهابات المزمنة.\", \"• يحسن صحة القلب: يخفض الكوليسترول الضار ويحمي الأوعية.\", \"• قد يقلل خطر السكتة الدماغية.\", \"• يحمي من مرض الزهايمر.\", \"• مفيد لمرضى السكري من النوع الثاني.\", \"• يساعد في الوقاية من بعض السرطانات.\", \"• ملعقتان كبيرتان يومياً كافية.\", \"• اختر النوع البكر الممتاز (Extra Virgin).\"]', 'التغذية', '[\"فوائد\", \"زيت\", \"الزيتون\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(67, 'كم ساعة نوم يحتاجها الإنسان؟', 'كم ساعه نوم يحتاجها الانسان', 'احتياجات النوم تختلف حسب العمر، والمدة الموصى بها للحفاظ على صحة جيدة.', '😴 ساعات النوم الموصى بها', '[\"• حديثو الولادة (0-3 شهور): 14-17 ساعة.\", \"• الرضع (4-11 شهر): 12-15 ساعة.\", \"• الأطفال (1-2 سنة): 11-14 ساعة.\", \"• الأطفال ما قبل المدرسة (3-5): 10-13 ساعة.\", \"• الأطفال في سن المدرسة (6-13): 9-11 ساعة.\", \"• المراهقون (14-17): 8-10 ساعات.\", \"• البالغون (18-64): 7-9 ساعات.\", \"• كبار السن (65+): 7-8 ساعات.\", \"• قلة النوم المزمنة تزيد خطر السمنة، السكري، وأمراض القلب.\"]', 'عام', '[\"كم\", \"ساعة\", \"نوم\", \"يحتاج\", \"الإنسان\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(68, 'ما هي أعراض نقص فيتامين ب12؟', 'ما هي اعراض نقص فيتامين ب12', 'فيتامين ب12 ضروري للأعصاب وخلايا الدم الحمراء. نقصه شائع خاصة عند النباتيين وكبار السن.', '🧪 أعراض نقص ب12', '[\"• تعب وضعف عام.\", \"• شحوب أو اصفرار الجلد.\", \"• تنميل ووخز في اليدين والقدمين.\", \"• صعوبة في المشي واضطراب التوازن.\", \"• تغيرات في الذاكرة والتركيز.\", \"• التهاب اللسان وتقرحات الفم.\", \"• ضعف النظر.\", \"• تغيرات مزاجية (اكتئاب، ارتباك).\", \"• المصادر: اللحوم، البيض، الألبان، والحبوب المدعمة للنباتيين.\"]', 'فيتامينات', '[\"اعراض\", \"نقص\", \"فيتامين\", \"ب12\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(69, 'ما هي أعراض حساسية اللاكتوز؟', 'ما هي اعراض حساسيه اللاكتوز', 'حساسية اللاكتوز (عدم تحمل اللاكتوز) هي عدم القدرة على هضم سكر الحليب بسبب نقص إنزيم اللاكتاز.', '🥛 أعراض عدم تحمل اللاكتوز', '[\"• تظهر الأعراض بعد 30 دقيقة إلى ساعتين من تناول منتجات الألبان.\", \"• انتفاخ وغازات.\", \"• تقلصات وألم في البطن.\", \"• إسهال مائي.\", \"• غثيان (قد يصل إلى قيء).\", \"• تختلف شدتها حسب كمية اللاكتوز المستهلكة.\", \"• يمكن تناول منتجات خالية من اللاكتوز أو أقراص اللاكتاز.\", \"• بعض الناس يتحملون الزبادي والجبن القديم بشكل أفضل.\"]', 'الحساسية', '[\"اعراض\", \"حساسية\", \"اللاكتوز\", \"عدم\", \"تحمل\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(70, 'ما هو علاج النقرس؟', 'ما هو علاج النقرس', 'النقرس هو نوع من التهاب المفاصل يحدث بسبب تراكم بلورات حمض اليوريك في المفصل. يسبب نوبات ألم مفاجئة وشديدة.', '🦶 علاج النقرس', '[\"• النوبة الحادة: مضادات الالتهاب غير الستيرويدية (إيبوبروفين، نابروكسين).\", \"• الكولشيسين فعال إذا بدأ خلال 24 ساعة.\", \"• الكورتيكوستيرويدات للحالات الشديدة أو إذا تعذر استخدام الأخرى.\", \"• الوقاية طويلة المدى: أدوية خفض حمض اليوريك (ألوبورينول، فيبوكسوستات).\", \"• تغيير نمط الحياة: تجنب اللحوم الحمراء، المأكولات البحرية، الكحول.\", \"• شرب 2-3 لتر ماء يومياً.\", \"• تجنب المشروبات المحلاة بالسكر.\"]', 'العظام والمفاصل', '[\"علاج\", \"النقرس\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(71, 'ما هي أعراض الاكتئاب؟', 'ما هي اعراض الاكتئاب', 'الاكتئاب ليس مجرد حزن عابر، بل هو اضطراب نفسي يؤثر على المزاج والتفكير والجسم. يحتاج إلى علاج.', '😔 أعراض الاكتئاب', '[\"• حزن مستمر أو شعور بالفراغ معظم اليوم.\", \"• فقدان الاهتمام أو المتعة في الأنشطة المعتادة.\", \"• تغير في الوزن أو الشهية.\", \"• أرق أو نوم زائد.\", \"• تعار و فقدان طاقة.\", \"• شعور بالذنب أو انعدام القيمة.\", \"• صعوبة في التركيز أو اتخاذ القرارات.\", \"• أفكار عن الموت أو الانتحار.\", \"• أعراض جسدية مثل آلام بلا سبب عضوي.\", \"• يستجيب للعلاج النفسي والدوائي (مضادات الاكتئاب).\"]', 'الصحة النفسية', '[\"اعراض\", \"الاكتئاب\", \"الحزن\"]', 1, 'manual', 0, 0, 0, '2026-05-22 01:26:41', '2026-05-22 01:26:41'),
(72, 'ما اعراض الانيميا', 'ما اعراض الانيميا', 'الأنيميا هي نقص في عدد أو جودة كريات الدم الحمراء التي تحمل الأكسجين للجسم.', '🩸 أعراض الأنيميا (فقر الدم)', '\"[\\\"\\\\u2022 \\\\u062a\\\\u0639\\\\u0628 \\\\u0648\\\\u0625\\\\u0631\\\\u0647\\\\u0627\\\\u0642 \\\\u0639\\\\u0627\\\\u0645 \\\\u0648\\\\u0636\\\\u0639\\\\u0641 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u062a\\\\u0631\\\\u0643\\\\u064a\\\\u0632\\\", \\\"\\\\u2022 \\\\u0634\\\\u062d\\\\u0648\\\\u0628 \\\\u0627\\\\u0644\\\\u062c\\\\u0644\\\\u062f \\\\u0648\\\\u0627\\\\u0644\\\\u0623\\\\u063a\\\\u0634\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u0645\\\\u062e\\\\u0627\\\\u0637\\\\u064a\\\\u0629\\\", \\\"\\\\u2022 \\\\u0636\\\\u064a\\\\u0642 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u062a\\\\u0646\\\\u0641\\\\u0633 \\\\u0648\\\\u062a\\\\u0633\\\\u0627\\\\u0631\\\\u0639 \\\\u0636\\\\u0631\\\\u0628\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\", \\\"\\\\u2022 \\\\u062f\\\\u0648\\\\u0627\\\\u0631 \\\\u0623\\\\u0648 \\\\u0635\\\\u062f\\\\u0627\\\\u0639 \\\\u062e\\\\u0635\\\\u0648\\\\u0635\\\\u0627\\\\u064b \\\\u0639\\\\u0646\\\\u062f \\\\u0627\\\\u0644\\\\u0648\\\\u0642\\\\u0648\\\\u0641\\\", \\\"\\\\u2022 \\\\u0628\\\\u0631\\\\u0648\\\\u062f\\\\u0629 \\\\u0627\\\\u0644\\\\u0623\\\\u0637\\\\u0631\\\\u0627\\\\u0641 \\\\u0648\\\\u062a\\\\u0633\\\\u0627\\\\u0642\\\\u0637 \\\\u0627\\\\u0644\\\\u0634\\\\u0639\\\\u0631\\\"]\"', 'عام', '\"[\\\"\\\\u0627\\\\u0639\\\\u0631\\\\u0627\\\\u0636\\\", \\\"\\\\u0627\\\\u0644\\\\u0627\\\\u0646\\\\u064a\\\\u0645\\\\u064a\\\\u0627\\\"]\"', 0.9, 'local', 1, 0, 0, '2026-05-09 16:59:14', '2026-05-09 16:59:14'),
(73, 'ورم البروستاتا', 'ورم البروستاتا', 'البروستاتا غدة صغيرة بحجم حبة الجوز تقع أسفل المثانة أمام المستقيم، وتحيط بالإحليل (القناة التي تنقل البول والمني).', '🫀 معلومات عن البروستاتا', '\"[\\\"\\u2022 \\u0648\\u0638\\u064a\\u0641\\u062a\\u0647\\u0627: \\u0625\\u0646\\u062a\\u0627\\u062c \\u0627\\u0644\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0645\\u0646\\u0648\\u064a \\u0627\\u0644\\u0630\\u064a \\u064a\\u063a\\u0630\\u064a \\u0648\\u064a\\u062d\\u0645\\u064a \\u0627\\u0644\\u062d\\u064a\\u0648\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0646\\u0648\\u064a\\u0629\\\", \\\"\\u2022 \\u062a\\u0636\\u062e\\u0645 \\u0627\\u0644\\u0628\\u0631\\u0648\\u0633\\u062a\\u0627\\u062a\\u0627 \\u0627\\u0644\\u062d\\u0645\\u064a\\u062f: \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0628\\u0648\\u0644\\u060c \\u0643\\u062b\\u0631\\u0629 \\u0627\\u0644\\u062a\\u0628\\u0648\\u0644 \\u0644\\u064a\\u0644\\u0627\\u064b\\u060c \\u0636\\u0639\\u0641 \\u062a\\u062f\\u0641\\u0642 \\u0627\\u0644\\u0628\\u0648\\u0644\\\", \\\"\\u2022 \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0628\\u0631\\u0648\\u0633\\u062a\\u0627\\u062a\\u0627: \\u0623\\u0644\\u0645 \\u0641\\u064a \\u0627\\u0644\\u062d\\u0648\\u0636 \\u0623\\u0648 \\u0623\\u0633\\u0641\\u0644 \\u0627\\u0644\\u0638\\u0647\\u0631\\u060c \\u0623\\u0644\\u0645 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062a\\u0628\\u0648\\u0644\\u060c \\u062d\\u0645\\u0649\\\", \\\"\\u2022 \\u0633\\u0631\\u0637\\u0627\\u0646 \\u0627\\u0644\\u0628\\u0631\\u0648\\u0633\\u062a\\u0627\\u062a\\u0627: \\u0642\\u062f \\u0644\\u0627 \\u062a\\u0638\\u0647\\u0631 \\u0623\\u0639\\u0631\\u0627\\u0636 \\u0645\\u0628\\u0643\\u0631\\u0629\\u060c \\u0648\\u0642\\u062f \\u064a\\u0633\\u0628\\u0628 \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0628\\u0648\\u0644 \\u0623\\u0648 \\u0648\\u062c\\u0648\\u062f \\u062f\\u0645 \\u0641\\u064a \\u0627\\u0644\\u0628\\u0648\\u0644\\\", \\\"\\u