--
-- Table structure for table `food_recommendations`
--

CREATE TABLE `food_recommendations` (
  `id` int(11) NOT NULL,
  `symptom_name` varchar(100) NOT NULL COMMENT 'اسم العرض',
  `foods_to_eat` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'أطعمة مفيدة (قائمة)',
  `foods_to_avoid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'أطعمة ممنوعة (قائمة)',
  `drinks_recommended` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'مشروبات مفيدة',
  `drinks_to_avoid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'مشروبات ممنوعة',
  `general_tips` text DEFAULT NULL COMMENT 'نصائح عامة',
  `severity_level` enum('خفيف','متوسط','شديد','الكل') DEFAULT 'الكل',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

