INSERT INTO `food_recommendations` (`id`, `symptom_name`, `foods_to_eat`, `foods_to_avoid`, `drinks_recommended`, `drinks_to_avoid`, `general_tips`, `severity_level`, `created_at`, `updated_at`) VALUES
(1, 'صداع', '[\"موز\", \"بطيخ\", \"زنجبيل\", \"شوفان\", \"لوز\", \"سبانخ\", \"سمك\"]', '[\"أجبان قديمة\", \"لحوم مصنعة\", \"شوكولاتة\", \"كافيين\", \"أطعمة مالحة\"]', '[\"ماء\", \"شاي زنجبيل\", \"عصير بطيخ\", \"شاي نعناع\"]', '[\"قهوة\", \"مشروبات غازية\", \"كحول\"]', 'تناول وجبات منتظمة وتجنب الجوع الطويل، اشرب كمية كافية من الماء، تجنب الأطعمة المحفزة للصداع', 'الكل', '2026-03-24 07:50:22', '2026-03-24 07:50:22'),
(2, 'دوخة', '[\"زنجبيل\", \"موز\", \"بطاطس\", \"عسل\", \"شوفان\", \"تفاح\"]', '[\"أطعمة مالحة\", \"كافيين\", \"كحول\", \"أطعمة دهنية\"]', '[\"شاي زنجبيل\", \"ماء جوز الهند\", \"عصير برتقال\", \"شاي نعناع\"]', '[\"قهوة\", \"مشروبات غازية\", \"كحول\"]', 'تناول وجبات صغيرة متكررة، اشرب سوائل كافية، تجنب الأطعمة التي تسبب الدوخة', 'الكل', '2026-03-24 07:50:22', '2026-03-24 07:50:22'),
(3, 'غثيان', '[\"زنجبيل\", \"موز\", \"تفاح\", \"أرز\", \"خبز محمص\", \"شوربة خضار\"]', '[\"أطعمة دهنية\", \"أطعمة حارة\", \"أجبان\", \"لحوم مصنعة\", \"مقليات\"]', '[\"شاي زنجبيل\", \"ماء\", \"عصير تفاح\", \"شاي نعناع\"]', '[\"قهوة\", \"عصائر حمضية\", \"مشروبات غازية\", \"كحول\"]', 'تناول أطعمة خفيفة وسهلة الهضم، اشرب سوائل ببطء، تجنب الروائح القوية', 'الكل', '2026-03-24 07:50:22', '2026-03-24 07:50:22'),
