--
-- Table structure for table `health_analytics`
--

CREATE TABLE `health_analytics` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `analysis_type` enum('weight_prediction','symptom_pattern','medication_effect','nutrition_advice') NOT NULL,
  `input_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`input_data`)),
  `output_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`output_data`)),
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `health_impact_factors`
--

CREATE TABLE `health_impact_factors` (
  `id` int(11) NOT NULL,
  `factor_type` enum('symptom','medicine','disease') NOT NULL,
  `factor_id` int(11) DEFAULT NULL COMMENT 'معرف العامل المرتبط (مثلاً معرف العرض أو الدواء)',
  `factor_name` varchar(100) NOT NULL,
  `impact_on_steps` int(11) NOT NULL COMMENT 'نسبة التأثير على هدف الخطوات (بالنسبة المئوية - سالب للتقليل، موجب للزيادة)',
  `calories_adjustment` int(11) DEFAULT NULL COMMENT 'تعديل السعرات (بالمئوية)',
  `water_adjustment` float DEFAULT 0 COMMENT 'تعديل كمية الماء (باللتر)',
  `protein_adjustment` float DEFAULT 0 COMMENT 'تعديل البروتين (بالجرام)',
  `carbs_adjustment` float DEFAULT 0 COMMENT 'تعديل الكربوهيدرات (بالجرام)',
  `fat_adjustment` float DEFAULT 0 COMMENT 'تعديل الدهون (بالجرام)',
  `severity_level` enum('خفيف','متوسط','شديد','الكل') DEFAULT 'الكل',
  `severity_weight` float DEFAULT 1 COMMENT 'وزن شدة التأثير (1.0 افتراضي)',
  `description` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

