--
-- Table structure for table `health_tips`
--

CREATE TABLE `health_tips` (
  `id` int(11) NOT NULL,
  `tip_category` enum('general','abnormal_low','abnormal_high','critical','prevention','lifestyle') NOT NULL,
  `related_analysis_type_id` int(11) DEFAULT NULL COMMENT 'مرتبط بنوع تحليل معين',
  `related_indicator_id` int(11) DEFAULT NULL COMMENT 'مرتبط بمؤشر معين',
  `condition_type` enum('low','high','both','always') DEFAULT 'always',
  `severity` enum('info','warning','danger') DEFAULT 'info',
  `title_ar` varchar(200) NOT NULL,
  `title_en` varchar(200) NOT NULL,
  `tip_text_ar` text NOT NULL,
  `tip_text_en` text NOT NULL,
  `recommendations_ar` text DEFAULT NULL COMMENT 'توصيات مفصلة',
  `recommendations_en` text DEFAULT NULL,
  `icon_code` varchar(50) DEFAULT '?',
  `priority` int(11) DEFAULT 0,
