INSERT INTO `health_tips` (`id`, `tip_category`, `related_analysis_type_id`, `related_indicator_id`, `condition_type`, `severity`, `title_ar`, `title_en`, `tip_text_ar`, `tip_text_en`, `recommendations_ar`, `recommendations_en`, `icon_code`, `priority`, `is_active`, `created_at`) VALUES
(1, 'general', NULL, NULL, 'always', 'info', 'نصيحة عامة للصحة', 'General Health Tip', 'احرص على شرب كمية كافية من الماء يومياً', 'Make sure to drink enough water daily', 'يوصى بشرب 8 أكواب من الماء يومياً للحفاظ على ترطيب الجسم', NULL, '💧', 1, 1, '2026-03-09 01:24:20'),
(2, 'general', NULL, NULL, 'always', 'info', 'النشاط البدني', 'Physical Activity', 'ممارسة الرياضة بانتظام تحسن صحتك العامة', 'Regular exercise improves your overall health', 'يوصى بممارسة 30 دقيقة من المشي يومياً', NULL, '🚶', 2, 1, '2026-03-09 01:24:20'),
(3, 'general', NULL, NULL, 'always', 'info', 'النوم الكافي', 'Adequate Sleep', 'احرص على النوم 7-8 ساعات يومياً', 'Make sure to sleep 7-8 hours daily', 'النوم الكافي يساعد في تجديد الطاقة وتحسين المزاج', NULL, '😴', 3, 1, '2026-03-09 01:24:20'),
(4, 'general', NULL, NULL, 'always', 'info', 'التغذية المتوازنة', 'Balanced Nutrition', 'تناول وجبات متوازنة تحتوي على جميع العناصر الغذائية', 'Eat balanced meals containing all nutrients', 'احرص على تناول الخضروات والفواكه والبروتينات', NULL, '🥗', 4, 1, '2026-03-09 01:24:20'),
(5, 'abnormal_low', NULL, 1, 'low', 'warning', 'انخفاض الهيموجلوبين - أنيميا', 'Low Hemoglobin - Anemia', 'نتيجة الهيموجلوبين لديك أقل من المعدل الطبيعي، مما يشير إلى احتمالية وجود أنيميا (فقر دم)', 'Your hemoglobin is below normal, indicating possible anemia', 'تناول أطعمة غنية بالحديد مثل: السبانخ، الكبد، اللحوم الحمراء، البقوليات\nتناول فيتامين C مع الحديد لتحسين الامتصاص (مثل عصير الليمون)\nاستشر طبيبك لتحديد سبب الأنيميا', NULL, '🩸', 5, 1, '2026-03-09 01:24:20'),
(6, 'abnormal_low', NULL, 2, 'low', 'warning', 'انخفاض الهيموجلوبين - أنيميا', 'Low Hemoglobin - Anemia', 'نتيجة الهيموجلوبين لديك أقل من المعدل الطبيعي، مما يشير إلى احتمالية وجود أنيميا (فقر دم)', 'Your hemoglobin is below normal, indicating possible anemia', 'تناول أطعمة غنية بالحديد مثل: السبانخ، الكبد، اللحوم الحمراء، البقوليات\nتناول فيتامين C مع الحديد لتحسين الامتصاص (مثل عصير الليمون)\nاستشر طبيبك لتحديد سبب الأنيميا', NULL, '🩸', 5, 1, '2026-03-09 01:24:20'),
(7, 'abnormal_high', NULL, 18, 'high', 'danger', 'ارتفاع مستوى السكر', 'High Blood Sugar', 'مستوى السكر في الدم أعلى من الطبيعي، قد يشير ذلك إلى مقدمات السكري أو مرض السكري', 'Your blood sugar is above normal, may indicate prediabetes or diabetes', 'قلل من تناول السكريات والنشويات البسيطة\nزد من تناول الألياف والخضروات\nمارس الرياضة بانتظام\nتابع مع طبيبك لإجراء الفحوصات اللازمة', NULL, '🍬', 5, 1, '2026-03-09 01:24:20'),
(8, 'abnormal_low', NULL, 18, 'low', 'danger', 'انخفاض مستوى السكر', 'Low Blood Sugar', 'مستوى السكر في الدم أقل من الطبيعي (نقص سكر الدم)', 'Your blood sugar is below normal (hypoglycemia)', 'تناول مصدر سريع للسكر مثل: عصير فواكه، أو حلوى، أو أقراص الجلوكوز\nتناول وجبة صغيرة تحتوي على كربوهيدرات معقدة\nإذا كنت تتناول أدوية للسكري، استشر طبيبك فقد تحتاج لتعديل الجرعة', NULL, '🍬', 5, 1, '2026-03-09 01:24:20'),
(9, 'abnormal_high', NULL, 22, 'high', 'warning', 'ارتفاع الكوليسترول', 'High Cholesterol', 'نسبة الكوليسترول الكلي أعلى من الموصى به', 'Your total cholesterol is above recommended levels', 'قلل من تناول الدهون المشبعة والمتحولة\nزد من تناول الألياف والشوفان\nتناول الأسماك الدهنية الغنية بأوميغا-3\nمارس الرياضة بانتظام', NULL, '🧪', 5, 1, '2026-03-09 01:24:21'),
(10, 'abnormal_low', NULL, 26, 'low', 'warning', 'انخفاض الكوليسترول الجيد HDL', 'Low HDL Cholesterol', 'نسبة HDL (الكوليسترول الجيد) منخفضة، مما يزيد من خطر أمراض القلب', 'Your HDL (good cholesterol) is low, increasing heart disease risk', 'مارس التمارين الرياضية بانتظام\nتناول الدهون الصحية مثل زيت الزيتون والأفوكادو والمكسرات\nتوقف عن التدخين إذا كنت مدخناً\nحافظ على وزن صحي', NULL, '❤️', 5, 1, '2026-03-09 01:24:21'),
(11, 'abnormal_high', NULL, 23, 'high', 'warning', 'ارتفاع الدهون الثلاثية', 'High Triglycerides', 'نسبة الدهون الثلاثية مرتفعة، مما يزيد من خطر أمراض القلب والتهاب البنكرياس', 'Your triglycerides are high, increasing heart disease and pancreatitis risk', 'قلل من السكريات والنشويات المكررة\nقلل من تناول الكحول\nتناول الأسماك الدهنية\nحافظ على وزن صحي', NULL, '🧪', 5, 1, '2026-03-09 01:24:21'),
(12, 'abnormal_high', NULL, 27, 'high', 'warning', 'ارتفاع إنزيمات الكبد', 'Elevated Liver Enzymes', 'إنزيمات الكبد (ALT/AST) مرتفعة، مما قد يشير إلى إجهاد أو التهاب في الكبد', 'Your liver enzymes are elevated, may indicate liver stress or inflammation', 'تجنب الكحول تماماً\nقلل من تناول الدهون والسكريات\nاشرب القهوة باعتدال (قد تساعد في حماية الكبد)\nاستشر طبيبك لتحديد السبب', NULL, '🫀', 5, 1, '2026-03-09 01:24:21'),
(13, 'abnormal_high', NULL, 36, 'high', 'warning', 'ارتفاع الكرياتينين', 'High Creatinine', 'نسبة الكرياتينين مرتفعة، مما قد يشير إلى ضعف في وظائف الكلى', 'Your creatinine is high, may indicate kidney function impairment', 'اشرب كمية كافية من الماء\nقلل من تناول البروتين الحيواني\nقلل من تناول الملح\nتجنب مضادات الالتهاب غير الستيرويدية (مثل الإيبوبروفين)\nاستشر طبيب الكلى', NULL, '🫁', 5, 1, '2026-03-09 01:24:21'),
(14, 'abnormal_low', NULL, 45, 'low', 'warning', 'نقص فيتامين د', 'Vitamin D Deficiency', 'مستوى فيتامين د لديك منخفض، وهو ضروري لصحة العظام والمناعة', 'Your vitamin D is low, essential for bone health and immunity', 'تعرض للشمس يومياً لمدة 15-20 دقيقة\nتناول أطعمة غنية بفيتامين د مثل: الأسماك الدهنية، صفار البيض، الكبد\nتناول مكملات فيتامين د تحت إشراف الطبيب', NULL, '☀️', 5, 1, '2026-03-09 01:24:21'),
(15, 'abnormal_low', NULL, 47, 'low', 'warning', 'نقص فيتامين ب12', 'Vitamin B12 Deficiency', 'مستوى فيتامين ب12 لديك منخفض، مما قد يسبب فقر الدم ومشاكل عصبية', 'Your vitamin B12 is low, may cause anemia and neurological issues', 'تناول أطعمة غنية بب12 مثل: اللحوم، الكبد، الأسماك، البيض، منتجات الألبان\nإذا كنت نباتياً، قد تحتاج لمكملات ب12\nاستشر طبيبك لتحديد الجرعة المناسبة', NULL, '💊', 5, 1, '2026-03-09 01:24:21'),
(16, 'abnormal_low', NULL, 48, 'low', 'warning', 'نقص الحديد', 'Iron Deficiency', 'مخزون الحديد في جسمك منخفض، مما قد يسبب أنيميا نقص الحديد', 'Your iron stores are low, may cause iron deficiency anemia', 'تناول أطعمة غنية بالحديد: اللحوم الحمراء، الكبد، السبانخ، البقوليات\nتناول فيتامين C مع الحديد (مثل: عصير ليمون مع السبانخ)\nقلل من الشاي والقهوة بعد الوجبات لأنها تقلل امتصاص الحديد\nاستشر طبيبك لتناول مكملات الحديد', NULL, '⚙️', 5, 1, '2026-03-09 01:24:21'),
(17, 'abnormal_high', NULL, 39, 'high', 'warning', 'ارتفاع حمض اليوريك - خطر النقرس', 'High Uric Acid - Gout Risk', 'نسبة حمض اليوريك مرتفعة، مما يزيد من خطر الإصابة بالنقرس', 'Your uric acid is high, increasing gout risk', 'قلل من تناول اللحوم الحمراء والأعضاء الداخلية (الكبد، الكلى)\nقلل من المأكولات البحرية\nتجنب الكحول خاصة الجعة\nاشرب الكثير من الماء\nحافظ على وزن صحي', NULL, '🦶', 5, 1, '2026-03-09 01:24:21'),
(18, 'abnormal_high', NULL, 40, 'high', 'warning', 'ارتفاع TSH - قصور الغدة الدرقية', 'High TSH - Hypothyroidism', 'نسبة TSH مرتفعة، مما يشير إلى قصور في نشاط الغدة الدرقية', 'Your TSH is high, indicating underactive thyroid', 'استشر طبيب الغدد الصماء\nقد تحتاج إلى علاج بهرمون الثيروكسين\nتناول الدواء بانتظام كما يصفه الطبيب\nتجنب تناول مكملات الحديد والكالسيوم مع دواء الغدة', NULL, '🧬', 5, 1, '2026-03-09 01:24:21'),
(19, 'abnormal_low', NULL, 40, 'low', 'warning', 'انخفاض TSH - فرط الغدة الدرقية', 'Low TSH - Hyperthyroidism', 'نسبة TSH منخفضة، مما يشير إلى فرط في نشاط الغدة الدرقية', 'Your TSH is low, indicating overactive thyroid', 'استشر طبيب الغدد الصماء\nتجنب المنبهات التي تحتوي على كافيين\nتناول وجبات صغيرة متكررة\nاحرص على الراحة وتجنب الإجهاد', NULL, '🧬', 5, 1, '2026-03-09 01:24:21'),
(20, 'abnormal_high', NULL, 5, 'high', 'warning', 'ارتفاع كرات الدم البيضاء', 'High WBCs', 'نسبة كرات الدم البيضاء مرتفعة، مما قد يشير إلى وجود التهاب أو عدوى في الجسم', 'Your white blood cells are high, may indicate infection or inflammation', 'إذا كان لديك أعراض مثل: حمى، تعب، ألم، استشر طبيبك\nإذا لم تكن هناك أعراض، قد يحتاج الطبيب لإعادة التحليل\nتناول السوائل الدافئة\nاحصل على قسط كاف من الراحة', NULL, '🩸', 5, 1, '2026-03-09 01:24:21'),
(21, 'abnormal_low', NULL, 6, 'low', 'danger', 'انخفاض الصفائح الدموية', 'Low Platelets', 'نسبة الصفائح الدموية منخفضة، مما يزيد من خطر النزيف', 'Your platelets are low, increasing bleeding risk', 'تجنب الأنشطة التي قد تسبب إصابات أو نزيف\nأخبر طبيب الأسنان قبل أي إجراء\nتجنب مضادات الالتهاب (مثل الأسبرين والإيبوبروفين)\nاستشر طبيب أمراض دم', NULL, '🩸', 5, 1, '2026-03-09 01:24:21'),
(22, 'general', NULL, NULL, 'always', 'info', 'استشارة الطبيب', 'Consult Your Doctor', 'نتيجة التحليل غير طبيعية، يُنصح باستشارة الطبيب', 'Your test result is abnormal, consult your doctor', 'خذ نتيجة التحليل معك عند زيارة الطبيب\nأخبر الطبيب بجميع الأدوية التي تتناولها\nاسأل الطبيب عن الفحوصات الإضافية إن لزم الأمر', NULL, '👨‍⚕️', 3, 1, '2026-03-09 01:24:21'),
(23, 'prevention', NULL, NULL, 'always', 'info', 'المتابعة الدورية', 'Regular Follow-up', 'احرص على إجراء الفحوصات الدورية لمتابعة حالتك الصحية', 'Have regular check-ups to monitor your health', 'تابع مع طبيبك بانتظام\nاحتفظ بسجل لنتائج تحاليلك السابقة\nقارن النتائج لمعرفة تطور حالتك', NULL, '📅', 2, 1, '2026-03-09 01:24:21'),
(24, 'lifestyle', NULL, NULL, 'always', 'info', 'نمط حياة صحي', 'Healthy Lifestyle', 'نمط الحياة الصحي يحسن نتائج التحاليل', 'Healthy lifestyle improves test results', 'تغذية متوازنة\nنشاط بدني منتظم\nنوم كاف\nتجنب التدخين والكحول\nإدارة التوتر', NULL, '🌟', 2, 1, '2026-03-09 01:24:21'),
(25, 'critical', NULL, 65, 'high', 'danger', 'ارتفاع INR - خطر النزيف', 'High INR - Bleeding Risk', 'نسبة INR مرتفعة، مما يزيد من خطر النزيف لمستخدمي مميعات الدم', 'Your INR is high, increasing bleeding risk for anticoagulant users', 'اتصل بطبيبك فوراً\nتجنب الأنشطة التي قد تسبب إصابات\nراقب علامات النزيف (نزيف لثة، كدمات غير مبررة، بول أو براز دموي)\nتجنب مضادات الالتهاب', NULL, '💉', 5, 1, '2026-03-09 01:24:21');

