(1, 'فول وفلافل', 'فول مدمس بالزيت والكمون مع طعمية وطماطم وخيار', 'فطور', 'تثبيت', 'مصري', 450, 20, 55, 18, '[\"الكل\"]', '[\"150 جرام فول مدمس\", \"3 أقراص طعمية\", \"رغيف عيش بلدي\", \"خيار\", \"طماطم\", \"ملعقة زيت زيتون\"]', 'يسخن الفول ويضاف له الكمون والزيت. تقدم الطعمية ساخنة مع الخضار.', NULL, '2026-03-24 08:50:22'),
(2, 'فلافل', 'طعمية (فلافل) مع طحينة وسلطة', 'فطور', 'تثبيت', 'مصري', 380, 15, 45, 16, '[\"الكل\"]', '[\"4 أقراص طعمية\", \"2 ملعقة طحينة\", \"رغيف عيش\", \"جرجير\", \"طماطم\"]', 'تقدم الطعمية مع الطحينة والجرجير', NULL, '2026-03-24 08:50:22'),
(3, 'جبنة قريش بالطماطم', 'جبنة قريش مع طماطم وزيتون', 'فطور', 'تخسيس', 'مصري', 280, 20, 25, 10, '[\"السكري\", \"القلب\"]', '[\"150 جرام جبنة قريش\", \"خيارة\", \"طماطم\", \"زيتون أسود\", \"رغيف عيش أسمر\"]', 'تخلط الجبنة مع الخضار وتقدم مع العيش', NULL, '2026-03-24 08:50:22'),
(4, 'بيض بالجبنة', 'بيض مقلي مع جبنة بيضاء', 'فطور', 'زيادة', 'مصري', 400, 22, 30, 22, '[]', '[\"2 بيضة\", \"50 جرام جبنة بيضاء\", \"رغيف عيش\", \"خيار\", \"طماطم\"]', 'يقلي البيض مع الجبنة ويقدم مع الخضار', NULL, '2026-03-24 08:50:22'),
(5, 'فول بالزيت', 'فول مدمس بالزيت والليمون', 'فطور', 'تخسيس', 'مصري', 300, 15, 40, 8, '[\"السكري\", \"الكوليسترول\"]', '[\"150 جرام فول\", \"نصف رغيف عيش\", \"طماطم\", \"بصل\", \"ليمون\"]', 'يهرس الفول ويضاف له الزيت والليمون', NULL, '2026-03-24 08:50:22'),
(6, 'بطاطس بالبيض', 'بطاطس مقلية مع بيض', 'فطور', 'زيادة', 'مصري', 500, 18, 45, 28, '[]', '[\"2 بطاطس\", \"2 بيضة\", \"رغيف عيش\", \"جبنة\"]', 'تقلب البطاطس مع البيض', NULL, '2026-03-24 08:50:22'),
(7, 'كشري', 'الكشري المصري الشهير', 'فطور', 'تثبيت', 'مصري', 350, 12, 60, 8, '[]', '[\"100 جرام أرز\", \"50 جرام مكرونة\", \"50 جرام عدس\", \"بصل محمر\", \"صلصة\"]', 'يخلط الأرز والمكرونة والعدس ويقدم مع البصل المحمر والصلصة', NULL, '2026-03-24 08:50:22'),
(8, 'عجة بالبسطرمة', 'عجة بالبيض والبسطرمة', 'فطور', 'زيادة', 'مصري', 420, 18, 15, 28, '[]', '[\"3 بيضات\", \"50 جرام بسطرمة\", \"فلفل\", \"طماطم\"]', 'تخلط المكونات وتقلى في الزيت', NULL, '2026-03-24 08:50:22'),
