(1, 1, 'الكل', 'علاج منزلي', 'علاج الصداع في المنزل', '', 'استرح في غرفة مظلمة وهادئة، اشرب ماء، تجنب الشاشات، استخدم كمادات باردة على الجبهة.', '', '🧊', 5, '2026-03-10 04:25:12'),
(2, 1, 'شديد', 'متى تزور الطبيب', 'متى تزور الطبيب للصداع', '', 'إذا كان الصداع شديداً ومفاجئاً، أو مصحوباً بزغللة أو تيبس في الرقبة، توجه للطوارئ.', '', '🚨', 10, '2026-03-10 04:25:12'),
(3, 2, 'الكل', 'علاج منزلي', 'علاج الدوخة', '', 'اجلس أو استلق فوراً، اشرب ماء، تناول وجبة خفيفة إذا كنت جائعاً، قس السكر إذا كنت مريض سكري.', '', '💧', 5, '2026-03-10 04:25:12'),
(4, 4, 'شديد', 'عام', 'تحذير: ألم الصدر', '', '🚨 ألم الصدر عرض خطير. إذا كنت تعاني من ألم في الصدر مع عرق غزير أو ضيق تنفس، اتصل بالطوارئ فوراً.', '', '⚠️', 10, '2026-03-10 04:25:12'),
(5, 5, 'شديد', 'عام', 'تحذير: ضيق التنفس', '', '🚨 ضيق التنفس المفاجئ يحتاج تدخلاً طبياً فورياً. اجلس في وضع مريح واتصل بالطوارئ.', '', '🆘', 10, '2026-03-10 04:25:12'),
(6, 3, 'متوسط', 'علاج منزلي', 'علاج الغثيان', '', 'تناول وجبات خفيفة، اشرب سوائل ببطء، تجنب الروائح القوية، استرح.', '', '🍵', 5, '2026-03-10 04:25:12'),
(7, 6, 'الكل', 'علاج منزلي', 'خفض الحرارة', '', 'اشرب سوائل كثيرة، استخدم كمادات ماء فاتر، تناول خافض حرارة بعد استشارة الطبيب.', '', '🌡️', 5, '2026-03-10 04:25:12');

