CREATE TABLE `symptom_types` (
  `id` int(11) NOT NULL,
  `name_ar` varchar(100) NOT NULL COMMENT 'اسم العرض بالعربية',
  `name_en` varchar(100) NOT NULL COMMENT 'اسم العرض بالإنجليزية',
  `icon` varchar(10) DEFAULT '?' COMMENT 'أيقونة العرض',
  `category` varchar(50) DEFAULT NULL COMMENT 'التصنيف (عصبي - هضمي - تنفسي - ...)',
  `default_analysis` text DEFAULT NULL COMMENT 'تحليل افتراضي لهذا النوع من الأعراض',
  `common_causes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'الأسباب الشائعة بصيغة JSON',
  `recommended_actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'الإجراءات الموصى بها بصيغة JSON',
  `warning_signs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'علامات الخطر',
  `requires_immediate_care` tinyint(1) DEFAULT 0 COMMENT 'هل يحتاج عناية فورية؟',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

