INSERT INTO `symptom_types` (`id`, `name_ar`, `name_en`, `icon`, `category`, `default_analysis`, `common_causes`, `recommended_actions`, `warning_signs`, `requires_immediate_care`, `created_at`) VALUES
(1, 'صداع', 'Headache', '🤕', 'عصبي', 'الصداع قد يكون نتيجة للإجهاد، الجفاف، أو ارتفاع ضغط الدم. إذا كان مصحوباً بزغللة أو دوخة، قد يشير لارتفاع الضغط.', '[\"الإجهاد والتعب\", \"الجفاف\", \"ارتفاع ضغط الدم\", \"الصداع النصفي\", \"إجهاد العين\"]', '[\"قس ضغط الدم\", \"اشرب كمية كافية من الماء\", \"استرح في مكان هادئ ومظلم\", \"تجنب الشاشات (الهاتف - التلفاز)\"]', '[\"صداع مفاجئ وشديد\", \"صداع مع تيبس في الرقبة\", \"صداع بعد إصابة في الرأس\", \"صداع مع ضعف في الأطراف\"]', 0, '2026-03-10 04:25:12'),
(2, 'دوخة', 'Dizziness', '😵', 'عصبي', 'الدوخة قد تكون بسبب انخفاض السكر، الجفاف، أو مشاكل في الأذن الداخلية. إذا كانت مصحوبة بطنين أو فقدان توازن، قد تشير لمشكلة في الأذن.', '[\"انخفاض السكر\", \"الجفاف\", \"مشاكل الأذن الداخلية\", \"فقر الدم\", \"القلق والتوتر\"]', '[\"قس السكر إذا كنت مريض سكري\", \"اشرب ماء\", \"اجلس أو استلق فوراً\", \"تناول وجبة خفيفة\"]', '[\"دوخة مع فقدان الوعي\", \"دوخة مع ألم في الصدر\", \"دوخة مع تداخل في الكلام\", \"دوخة مستمرة لساعات\"]', 0, '2026-03-10 04:25:12'),
(3, 'غثيان', 'Nausea', '🤢', 'هضمي', 'الغثيان قد يكون بسبب عسر هضم، تسمم غذائي، أو دوار الحركة. إذا كان مصحوباً بقيء شديد، قد يؤدي للجفاف.', '[\"عسر الهضم\", \"تسمم غذائي\", \"دوار الحركة\", \"الحمل\", \"الصداع النصفي\"]', '[\"تناول وجبات خفيفة\", \"تجنب الأطعمة الدهنية\", \"اشرب سوائل ببطء\", \"استرح\"]', '[\"قيء مستمر\", \"قيء دموي\", \"ألم شديد في البطن\", \"جفاف شديد\"]', 0, '2026-03-10 04:25:12'),
(4, 'ألم صدر', 'Chest Pain', '💔', 'قلبي', '🚨 هذا عرض خطير قد يشير لمشكلة في القلب. يجب التوجه للطوارئ فوراً خاصة إذا كان مصحوباً بعرق غزير أو ضيق تنفس.', '[\"مشاكل القلب\", \"القلق\", \"مشاكل الجهاز التنفسي\", \"ارتجاع المريء\"]', '[\"اتصل بالطوارئ فوراً\", \"لا تقم بقيادة السيارة\", \"اجلس في وضع مريح\", \"حاول أن تهدأ\"]', '[\"ألم يمتد للذراع أو الفك\", \"ضيق في التنفس\", \"عرق بارد\", \"غثيان وقيء\"]', 1, '2026-03-10 04:25:12'),
(5, 'ضيق تنفس', 'Shortness of Breath', '😮‍💨', 'تنفسي', '🚨 ضيق التنفس عرض خطير قد يشير لمشكلة في القلب أو الرئتين. يحتاج تقييماً طبياً فورياً.', '[\"الربو\", \"الانسداد الرئوي\", \"قصور القلب\", \"القلق\", \"فقر الدم\"]', '[\"اتصل بالطوارئ\", \"اجلس في وضع مستقيم\", \"حاول التنفس ببطء\", \"استخدم بخاخ الربو إن وجد\"]', '[\"ألم في الصدر\", \"ازرقاق الشفاه\", \"عدم القدرة على التحدث\", \"دوخة شديدة\"]', 1, '2026-03-10 04:25:12'),
(6, 'حرارة', 'Fever', '🌡️', 'عام', 'ارتفاع الحرارة قد يشير لوجود التهاب في الجسم. إذا استمرت أكثر من 3 أيام أو كانت مرتفعة جداً، استشر طبيبك.', '[\"عدوى فيروسية\", \"عدوى بكتيرية\", \"التهاب\", \"ضربة شمس\"]', '[\"قس درجة الحرارة\", \"اشرب سوائل كثيرة\", \"استخدم كمادات\", \"تناول خافض حرارة\"]', '[\"حرارة أعلى من 40°م\", \"حرارة مع تيبس رقبة\", \"حرارة مع طفح جلدي\", \"حرارة مستمرة لأكثر من 3 أيام\"]', 0, '2026-03-10 04:25:12'),
(7, 'ألم بطن', 'Abdominal Pain', '🫄', 'هضمي', 'ألم البطن قد يكون بسبب عسر هضم، إمساك، أو التهاب. إذا كان شديداً أو مصحوباً بحرارة، استشر طبيبك.', '[\"عسر هضم\", \"إمساك\", \"التهاب المعدة\", \"متلازمة القولون العصبي\", \"حصوات المرارة\"]', '[\"تجنب الأطعمة الدسمة\", \"اشرب سوائل دافئة\", \"استرح\", \"تناول وجبات خفيفة\"]', '[\"ألم شديد ومفاجئ\", \"ألم مع حرارة\", \"قيء دموي\", \"انتفاخ شديد\"]', 0, '2026-03-10 04:25:12'),
(8, 'إسهال', 'Diarrhea', '🚽', 'هضمي', 'الإسهال قد يكون بسبب عدوى فيروسية أو بكتيرية. المهم تعويض السوائل المفقودة لتجنب الجفاف.', '[\"عدوى فيروسية\", \"تسمم غذائي\", \"حساسية غذائية\", \"التهاب القولون\", \"أدوية معينة\"]', '[\"اشرب سوائل كثيرة\", \"تجنب منتجات الألبان\", \"تناول أطعمة خفيفة\", \"استشر طبيباً إذا استمر\"]', '[\"إسهال دموي\", \"إسهال مع حرارة\", \"جفاف شديد\", \"إسهال مستمر لأكثر من 3 أيام\"]', 0, '2026-03-10 04:25:12'),
(9, 'تنميل', 'Numbness', '🫨', 'عصبي', 'التنميل قد يكون بسبب نقص فيتامينات، أو مشاكل في الأعصاب. إذا كان في جانب واحد، قد يشير لمشكلة خطيرة.', '[\"نقص فيتامين ب12\", \"الضغط على العصب\", \"السكري\", \"نقص الدورة الدموية\"]', '[\"تحقق من نسبة السكر\", \"حرك المنطقة المصابة\", \"استشر طبيب أعصاب\", \"تناول أطعمة غنية بفيتامين ب\"]', '[\"تنميل في جانب واحد\", \"تنميل مفاجئ\", \"تنميل مع ضعف\", \"تنميل بعد إصابة\"]', 0, '2026-03-10 04:25:12'),
(10, 'زغللة', 'Blurred Vision', '👁️', 'بصري', 'زغللة العين قد تكون بسبب إجهاد العين، أو قد تشير لارتفاع السكر أو الضغط. إذا كانت مفاجئة، فهي حالة طارئة.', '[\"إجهاد العين\", \"ارتفاع السكر\", \"ارتفاع الضغط\", \"الصداع النصفي\", \"مشاكل في النظر\"]', '[\"قس السكر\", \"قس الضغط\", \"أرح عينيك\", \"تجنب الشاشات\"]', '[\"زغللة مفاجئة\", \"زغللة مع صداع شديد\", \"فقدان البصر المفاجئ\", \"رؤية أضواء وامضة\"]', 1, '2026-03-10 04:25:12'),
(11, 'تعب', 'Fatigue', '😴', 'عام', 'التعب المستمر قد يكون بسبب فقر الدم، اضطرابات النوم، أو مشاكل الغدة الدرقية. إذا استمر لأكثر من أسبوعين، استشر طبيبك.', '[\"فقر الدم\", \"قلة النوم\", \"الغدة الدرقية\", \"الاكتئاب\", \"الإجهاد\"]', '[\"نم 7-8 ساعات\", \"تناول غذاء متوازن\", \"مارس الرياضة\", \"اشرب ماء كافياً\"]', '[\"تعب شديد ومفاجئ\", \"تعب مع فقدان وزن\", \"تعب مع حرارة\", \"تعب يمنع الأنشطة اليومية\"]', 0, '2026-03-10 04:25:12');

