--
-- Table structure for table `user_test_results`
--

CREATE TABLE `user_test_results` (
  `id` int(11) NOT NULL,
  `history_id` int(11) NOT NULL,
  `indicator_id` int(11) NOT NULL,
  `value` decimal(10,2) NOT NULL,
  `unit` varchar(30) DEFAULT NULL,
  `status` enum('normal','low','high','critical_low','critical_high') NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Triggers `user_test_results`
--
DELIMITER $$
CREATE TRIGGER `after_critical_result` AFTER INSERT ON `user_test_results` FOR EACH ROW BEGIN
    IF NEW.status IN ('critical_low', 'critical_high') THEN
        
        INSERT INTO user_alerts (user_id, alert_type, message, related_result_id)
        SELECT 
            uah.user_id,
            'critical',
            CONCAT('نتيجة حرجة: ', ti.name_ar, ' = ', NEW.value, ' ', ti.unit),
            NEW.id
        FROM user_analysis_history uah
        JOIN test_indicators ti ON NEW.indicator_id = ti.id
        WHERE uah.id = NEW.history_id;
    END IF;
END
$$
DELIMITER ;

